var e={common:{cancel:`取消`,"count.files":{other:`{count} 个文件`},"list.and":`{first} 和{second}`,"list.then":`{first}，然后是{second}`,"list.comma":`{first}、{second}`,"list.semicolon":`{first}；{second}`,"bank.slot":`槽位 {letter}`,"bank.recovery":`恢复槽位 {letter}`,"bank.slotInSentence":`槽位 {letter}`,"bank.recoveryInSentence":`恢复槽位 {letter}`},app:{title:`Seek Thermal 固件工具箱`,"header.cameraSelected":`已选择相机`,"header.noCamera":`未选择相机`,"header.usbUnavailable":`USB 不可用`,"header.github":`GitHub 上的本工具箱`,"header.tabs":`标签页`,"tab.info":`信息`,"tab.preserve":`导出并解密 0.x/1.x 2014/2016`,"tab.v4":`导出并解密 4.x/Nano`,"tab.decrypt":`解密文件/槽位`,"tab.slots":`固件槽位操作`,documentTitle:`Seek Thermal 固件 — {tab}（WebUSB）`,"theme.label":`深色主题`,"theme.followsSystem":`跟随系统的浅色或深色设置`,"theme.chosenDiffers":`已在此处选择。切换回来即可跟随系统设置。`,"theme.chosenSame":`已在此处选择，与系统当前的设置相同`,"language.label":`语言`,"intro.info":"像 `seek-fw info` 一样读取已连接的相机：它的固件、它的应答所对应的固件系列、启动方式、密钥以及每个槽位。它会告诉你哪个标签页适用于这台相机，并用通俗的话说明每个标签页的用途。**此标签页不会向闪存写入任何内容。**","intro.preserve":`适用于 **0.x 和 1.x** 相机（2014 年和 2016 年的版本）。为相机的 4 MB 闪存制作一份**完整**副本——包括普通导出读不到的部分——然后让相机完全恢复原样。它先备份能读取的内容，短暂地给固件打上补丁以便读取其余部分，导出全部内容，再还原原始固件并加以检查。一切都在你的浏览器本地运行。**其中两个步骤会写入闪存**，每一步执行前都会先征求你的确认。`,"intro.v4":`通过 WebUSB 以只读方式复制 **4.x 或 Nano** 相机的 4 MB SPI 闪存，并解密其中找到的所有固件镜像。一切都在你的浏览器本地运行——不会上传到任何地方。**只读：**此标签页不会发出任何闪存写入、擦除、上传、提交或重置命令。其他固件线的相机会在读取任何内容之前被拒绝。`,"intro.decrypt":`在这台电脑上解密你已有的固件：一份完整的闪存镜像，或单个 64 KB 固件槽位。**不使用相机**，因此不连接任何设备也能使用，在没有 USB 访问权限的浏览器中也能使用。文件只在本地读取，绝不上传。`,"intro.slots":`读取相机的三个固件槽位——槽位 A、槽位 B 和恢复槽位 R——显示每个槽位存放的内容、相机从哪个槽位启动，以及此版本能对它做什么，旁边列出设备正在运行的固件和密钥。一切都在你的浏览器本地运行。**此标签页会写入闪存：**它可以用解密后的镜像或原始字节写入一个槽位，并在每次写入前征求确认。`,"support.ios.title":`**iOS 和 iPadOS 上没有 WebUSB，**因此这台设备无法读取相机的闪存。`,"support.ios.body":`Safari 没有实现它，而 iOS 上的所有浏览器都必须使用 WebKit，所以这里的 Chrome 和 Firefox 也无法提供它。没有任何开关或扩展能改变这一点。要导出相机，请使用台式电脑，或带 USB-OTG 线的 Android 手机。`,"support.noWebUsb.title":`**此浏览器无法访问 USB 设备。**`,"support.noWebUsb.body":`WebUSB 可在 Windows、macOS、Linux 和 Android 上的 Chrome、Edge、Opera 及其他 Chromium 浏览器中使用。Firefox 和 Safari 都已拒绝实现它。`,"support.noWebUsb.insecure":`此页面也不是通过安全连接提供的，仅这一点就会阻止 WebUSB。`,"support.insecure.title":`**连接不安全。**此处已禁用 WebUSB。`,"support.insecure.body":"请通过 HTTPS 或从 `http://localhost` 打开此页面。像 `http://192.168.1.10:8000` 这样的普通局域网地址不符合要求。","support.offlineStillWorks":`你仍然可以使用 **{tab}** 标签页——它完全基于你选择的文件运行，不需要 USB 访问。`,"support.ready":`**准备就绪。**插上你的 Seek 相机，然后按 *{connect}*。`,"support.fileProtocol":`此页面是作为本地文件打开的，因此浏览器在重新加载后不会记住设备。这没有影响。`,unlockNote:`注意：{note}。`,"connect.title":`连接`,"connect.actions":`设备操作`,"connect.connect":`连接设备`,"connect.change":`更换设备`,"connect.test":`测试连接`,"connect.forget":`忘记设备`,"connect.vendorNote":"会列出所有 Seek Thermal 设备（USB 厂商 `{vendor}`）——Compact、Compact PRO、Nano 等。请在浏览器的设备选择框中选择你的相机。","platform.title":`平台说明`,"platform.macos":`在 Chrome、Edge 或任何 Chromium 浏览器中开箱即用。无需安装驱动，无需管理员权限。请先退出任何正在与相机通信的其他程序——同一时间只能有一个进程占用 USB 接口。`,"platform.linux.access":`给你的用户授予访问该设备的权限，然后拔下设备再重新插上：`,"platform.linux.sandbox":"Snap 和 Flatpak 版的 Chromium 常被沙盒隔离，无法访问原始 USB 设备；`.deb` 或 `.rpm` 版才可靠。","platform.windows":"Windows 需要先为相机绑定 WinUSB 驱动，浏览器才能访问它。使用 <zadig>Zadig</zadig>：*Options → List All Devices*，然后在下拉列表中选择以你的相机命名的条目——例如 `CompactPRO FF`——驱动选择 **WinUSB**，再点击 Replace Driver。如果你的相机出现不止一次，请选择标有 *(Interface 0)* 的条目。这样做之后，厂商软件将无法使用该设备，直到你在设备管理器中撤销（*卸载设备 → 删除驱动程序*，然后重新插上）。","platform.android":`在 Android 版 Chrome 中配合 USB-OTG 线使用，前提是手机能为相机提供总线供电。Android 会通过它自己的权限对话框授予 USB 访问权限。下载的文件会像其他文件一样保存到“下载”文件夹。`,"platform.ios.name":`iPhone 和 iPad`,"platform.ios.cannot":`**无法读取相机**，而且这一点不会改变。Safari 没有实现 WebUSB，而在 iOS 和 iPadOS 上，所有浏览器——包括 Chrome 和 Firefox——都必须使用 WebKit 渲染，因此它们都不提供这个接口。没有任何开关、扩展或应用可以绕过这一点。请使用台式电脑或 Android 手机进行导出。`,"platform.ios.decrypt":`可选的解密功能在这里可以使用：解密你已有的镜像文件不需要 USB 访问，所以你可以在 iPhone 或 iPad 上，或者在台式电脑的 Firefox 和 Safari 中进行。`},core:{"unlock.powerCycleNote":`相机在断电重启之前会一直保持解锁状态，在此之前其他工具可能会误读它；使用其他工具之前，请先给相机断电重启`,"boot.rule":`先 {first}，然后 {second}，最后 {last}`,"boot.verdict.notRead":`没有被读取`,"boot.verdict.checkKeyUnnamed":`无法检查：没有指明其引导程序检查槽位时使用的密钥`,"boot.cfg0NotRead":`没有读取启动配置字（cfg[0]），因此不知道下次启动会运行哪个槽位`,"boot.select.unknown":`启动配置字为 {word}，因此引导程序先尝试{first}，但{bank} {verdict}，所以不知道会运行哪个槽位`,"boot.select.first":`启动配置字为 {word}，因此引导程序先尝试{first}，其中有引导程序接受的镜像`,"boot.select.second":`启动配置字为 {word}，因此引导程序先尝试{first}；{first} 中没有引导程序接受的镜像，所以它会使用{second}`,"boot.select.lastBoots":`启动配置字为 {word}，因此引导程序先尝试{first}；{first} 和{second} 中都没有引导程序接受的镜像，所以它会启动{last}，且不对其进行检查`,"boot.select.lastTakes":`启动配置字为 {word}，因此引导程序先尝试{first}；{first} 和{second} 中都没有引导程序接受的镜像，所以它会使用{last}，且不对其进行检查`,"boot.bootsNow":`{bank} 是相机当前启动的槽位`,"boot.bootedNow":`当前启动`,"boot.notBooted":`未启动`,"boot.unknownWhy.checkKeyUnnamed":`本次读取没有指明其引导程序检查槽位时使用的密钥`,"boot.unknownWhy.noKeyTable":`没有读取引导程序的密钥表，因此无法说出它会尝试哪些密钥`,"fpsBoot.boots":`相机启动的是{bank}。{why}。`,"fpsBoot.holdsOne":`{bank} 中有帧率补丁，但它不会运行，所以补丁不会生效。`,"fpsBoot.holdsTwo":`{banks} 中有帧率补丁，但它们都不会运行，所以这些补丁不会生效。`,"fpsBoot.wouldNotRun":`修补{target} 并不会让它运行，因为相机启动的是{bank}。`,"fpsBoot.patchRunning":`也请修补{bank}（运行的那个槽位）：这样帧率补丁才会生效。`,"fpsBoot.cannotPatch":`{bank} 无法在这里修补（{reason}），所以其他槽位中的帧率补丁在这台相机上不会生效。`,"backup.bank.notInPlan":`{name}（不在此版本的计划中：zip 中有说明）`,"backup.bank.unsupported":`{name}（此版本无法读取它，{reason}：zip 中有说明）`,"backup.bank.empty":`{name}（空，每个字节都是 0xFF：zip 中有说明，这次写入不会覆盖任何固件）`,"backup.bank.unread":`{name}（槽位读取没有读到它：zip 中会说明写入前的读取是否读到）`,"backup.bank.noKey":`{name}（按存储原样；本次读取恢复的密钥都无法打开它，所以没有解密文件）`,"backup.bank.decrypted":`{name}（按存储原样，并已解密）`,"backup.plan.one":`在写入任何内容之前，会重新读取{banks}，并与说明每个文件内容的备注一起保存到一个 zip 中：{file}。`,"backup.plan.many":`在写入任何内容之前，会重新读取{banks}，并与说明每个文件内容的备注一起保存到一个 zip 中：{file}。`,"staging.detail.keyACiphertext":`加密后使设备以当前启动槽位持有的密钥存储它`,"staging.detail.slotKeystreamCiphertext":`以镜像自己的暂存密钥（密钥块 0）加密；相机会以该槽位自己的密钥存储它`,"staging.detail.plain":`明文，不加密`,"staging.detail.keyAKeystream":`按厂商应用暂存 1.3.0.8 FF 镜像的方式（XOR 密钥 A）——16 Hz 版本会以密钥 B 存储它，而不是存储这些字节`,"staging.detail.verbatim":`原样——字节完全按给定的内容`,"copy.source.noRead":`没有读取`,"copy.source.notInPlan":`{name} 不在此版本的计划中`,"copy.source.notRead":`{name} 没有被读取（{reason}），所以没有可复制的镜像`,"copy.source.empty":`{name} 是空的：没有可复制的镜像`,"copy.source.foreign":`{name} 中没有本次读取能识别的固件镜像，所以没有可复制的内容`,"copy.source.noKey":`本次读取恢复的密钥都无法打开{name}，所以没有可复制的解密镜像`,"copy.from":`{name}（{address}），按槽位读取时的解密结果`,"copy.fromVersion":`{name}（{address}），固件 {version}，按槽位读取时的解密结果`,"copy.note":`镜像来自{name}，按槽位读取时的解密结果：{size} B，sha256 {sha256}。`,"copy.noteVersion":`镜像来自{name}，按槽位读取时的解密结果：固件 {version}，{size} B，sha256 {sha256}。`,"restore.where":`备份中的{name}（{address}）`,"restore.from":`{where}，位于完整闪存备份 {file} 中`,"restore.fromVersion":`{where}，位于完整闪存备份 {file} 中，固件 {version}`,"restore.kind.flash-file":`一个 4 MB 闪存镜像`,"restore.kind.preserve-run":`一个 Preserve 运行文件`,"restore.kind.dump":`一个“导出并解密 4.x/Nano”的 zip`,"restore.kind.all-selectors":`一个“导出全部选择器”的 zip`,"restore.decryptedTo.image":`一个镜像`,"restore.decryptedTo.firmware":`固件 {version}`,"restore.note.image":`镜像是 {file}（{kind}）中的{where}：存储内容 sha256 {stored}，解密为 {size} B 的{decrypted}（sha256 {sha256}）。`,"restore.note.imageEntry":`镜像是 {file}（{kind}，其中的 {entry}）中的{where}：存储内容 sha256 {stored}，解密为 {size} B 的{decrypted}（sha256 {sha256}）。`,"restore.note.readBack":`写入之后，会把回读的槽位与备份中存储的槽位字节进行比对。`,"restore.note.sameCamera":`备份的身份信息块指明的正是这台相机（序列号 {serial}）。`,"restore.note.sameBytes":`{name} 中已经是备份存储的字节：这次写入会把同一个镜像放回去。`,"restore.warn.otherCamera":`这个备份看起来来自另一台相机：它的身份信息块中的序列号是 {theirs}，而这台相机是 {camera}。只会写入{name} 的镜像；那台相机的身份信息和校准数据都不会写入。`,"restore.warn.noIdentity":`这个备份在 {address} 处没有身份信息块，因此无法判断它是从谁的相机读取的。`,"restore.warn.serialNotRead":`没有读取相机的序列号，因此无法把备份（序列号 {serial}）与它对应起来。`,"restore.warn.otherFirmware":`{where}中是固件 {version}，而相机运行的是 {camera}：这次还原会把另一个固件放进该槽位。`,"restore.readBack.notCompared":`{bank} 没有回读，因此没有与备份比对。`,"restore.readBack.equal":`{bank} 的回读结果与备份中存储的内容逐字节相同。`,"restore.readBack.differs":`{bank} 的回读结果与备份中存储的字节有 {count} B 不同（第一处在 {offset}）。`,"keys.derived.same":`{key}，由当前启动的{bank} 推导得出`,"keys.derived.holds":`{key}（存储密钥），由当前启动的{bank} 推导得出，该槽位持有{holds}`,"keys.derived.sameUnnamed":`{key}，由当前启动的槽位推导得出`,"keys.derived.holdsUnnamed":`{key}（存储密钥），由当前启动的槽位推导得出，该槽位持有{holds}`,"keys.ffVendor.staged":`按厂商应用暂存的方式处理 1.3.0.8 FF（16 Hz）镜像：镜像 XOR 它自己的密钥块 0（密钥 A），头部窗口保持原样，可写入任何槽位；不使用这台相机的密钥`,"keys.ffVendor.stored":`密钥 B：相机用密钥块 1 重新加密上传的数据，并以它存储镜像`,"keys.imageBlock0.staged":`以镜像自己的密钥块 0（按值在镜像中找到）加密，可写入任何槽位；不使用这台相机的密钥`,"keys.imageBlock0.storedUnnamed":`其引导程序检查槽位时使用的密钥（本次读取未指明）；相机会以它重新加密上传的数据`,"keys.imageBlock0.stored":`{key}，即其引导程序检查槽位时使用的密钥；相机会以它重新加密上传的数据`,"notes.ffBootUntested":`UNTESTED（未经测试）：还没有从任何相机上读取过 16 Hz FF 版本的引导程序，因此不知道写入的槽位能否启动。在 0.9.0.0 引导程序上，这个镜像的较早形式曾从恢复槽位 R 启动；这种形式则不会，因为该引导程序按存储原样启动恢复槽位 R，不会对其解码。`,"write.ff.otherVersion":`16 Hz FF 镜像以只有 16 Hz {version} 版本才能读取的形式发送。这台相机写入槽位时不检查镜像（它的固件源代码如此，一台 1.3.0.0 Compact 在试验中也是这样），因此预计它会按发送的原样写入这些字节：之后该槽位中存放的镜像是这台相机无法启动的形式。`,"write.ff.untested":`{untested}这里没有任何内容声称相机能启动它。`,"write.ff.runsFast":`相机自己的应答表明它运行的是 16 Hz FF 版本：{why}。`,"write.ff.outcome.takes":`会在擦除槽位之前检查载荷，而这个载荷能通过检查，所以它可能会按原样写入这些字节，而这种形式是其引导程序无法启动的：该槽位可能无法启动（未经尝试；写入前保存的备份可以把它恢复回去）`,"write.ff.outcome.refuses":`会在擦除槽位之前检查载荷，而这个载荷无法通过检查，所以预计它会在写入任何内容之前拒绝这次写入（一台运行该版本的相机曾以同样的方式拒绝过这个镜像的较早形式）`,"write.ff.runsSlow":`相机运行的是 8 Hz {version} 版本：{why}。该版本{outcome}。`,"write.ff.buildUnknown":`相机自己的应答没有表明它运行的是哪个 {version} 版本：{why}。如果它运行的是 16 Hz FF 版本，它会接受这个载荷。如果它运行的是 8 Hz 版本，该版本{outcome}。`,"write.raw.asGiven":`原始载荷：完全按给定的内容发送。这里不会检查它是否可启动。`,"write.raw.ffStagedForm":`这个载荷是 1.3.0.8 FF 的暂存形式（镜像 XOR 密钥块 0，字累加和 0xFFFF）。相机会以密钥 B 存储镜像，所以回读结果会与那些字节比对。`,"write.raw.noStaging":`此版本没有为该槽位指定暂存形式，因此无法说明引导程序的检查情况。`,"write.raw.reencrypts":`设备会解码这个载荷，并重新加密它保存的内容，所以无法预测存储的字节。在能够判断的情况下，回读结果会按它解密后的镜像进行检查。`,"write.raw.bootloaderRejects":`引导程序会拒绝这个载荷：{failure}。`,"write.raw.stageKeyUnchecked":`原始字节中不含 2016 年的暂存密钥（密钥块 0），所以这里不检查这个载荷解密后的字累加和。`,"write.image.rekeyRisk":`{name} 中已经存放着引导程序无法接受的镜像。这次写入的结果会是同样的状态。`,"write.ack.recovery":`恢复槽位 R：写入它需要你确认已了解风险。这里不会检查相机之后能否启动。`,"write.ack.risk":`{risk}：写入它需要你确认已了解风险，下一次断电重启后，相机会运行其中存放的任何内容。`,"write.ack.bootUnnamed":`无法确定当前启动的槽位，因此这个槽位被视为当前启动的槽位`,"write.ack.recoveryFallback":`恢复槽位 R 是引导程序最后退回使用的副本`,"boot.cfg0.modernBlank":`空白/0：优先槽位 A，然后 B，然后恢复槽位`,"boot.cfg0.modernB":`优先槽位 B，然后 A，然后恢复槽位`,"boot.cfg0.modernRecovery":`优先恢复槽位，然后 A，然后 B`,"report.nextStart.unknown":`未知——{why}`,"report.nextStart.runs":`{bank}——{why}`,"upgrade.targetBooted":`{name} 既是相机本次启动的槽位，也是它自身升级时写入的槽位。从这台相机运行升级会覆盖它正在运行的镜像。这只是警告：这里不会阻止升级。`,"upgrade.whileRecovery":`相机正在运行它的恢复槽位，而它自身的升级会写入{name}，即它没有在运行的那个槽位。{verdict}这只是警告：这里不会阻止升级。`,"upgrade.verdict.notRead":`本次检查无法读取{name}，因此不知道其中存放的内容。`,"upgrade.verdict.blank":`{name} 是空白的，因此升级会写入一个空槽位。`,"upgrade.verdict.bootableSame":`{name} 中存放的可启动镜像与正在运行的槽位相同，升级会替换它；如果升级中途停止，{name} 将无法启动。`,"upgrade.verdict.bootable":`{name} 中存放着可启动的镜像，升级会替换它；如果升级中途停止，{name} 将无法启动。`,"upgrade.verdict.unknown":`本次读取无法确定{name} 是否可启动，因此升级可能会替换一个相机能够启动的镜像。`,"upgrade.verdict.notBootable":`本次读取没有显示{name} 可启动，因此升级不会替换任何相机能够启动的镜像。`,"report.booted.name":`{bank}`,"report.booted.entered":`{bank}——引导程序本次启动时进入的槽位（按其记录）`,"report.lastStart.notRead":`未读取`,"report.lastStart.noBank":`相机报告 {word}，它不对应任何槽位`,"report.lastStart.entered":`相机报告它进入了{bank}（活动槽位字 {word}）`,"running.noVersion":`无版本`,"running.why.otherVersion":`相机报告的是 {version}，而只有 {only} 才分两个版本`,"running.why.noVerdicts":`相机没有应答槽位判定（GetFirmwareInfo 选择器 6、7、8）`,"running.why.notRead":`判定所依赖的某个槽位没有被读取，因此无法预测应答`,"running.answers":`相机应答 {answers}`,"running.answers.each":`A {a}，B {b}，R {r}`,"running.why.plain":`{answers}，这正是 8 Hz 1.3.0.8 版本对这些槽位的应答（{predicted}）`,"running.why.ff":`{answers}，这正是 16 Hz FF 1.3.0.8 版本对这些槽位的应答（{predicted}）`,"running.why.both":`{answers}，而两个版本对这些槽位的应答完全相同，所以这些槽位无法区分它们`,"running.why.neither":`{answers}，与两个版本都不符（8 Hz：{plain}；16 Hz FF：{ff}）`,"imageBuild.noVersion":`这个镜像的头部没有注明固件版本，因此无法判断它是否就是相机运行的版本（{camera}）。请确认这是你要写入的镜像。`,"imageBuild.otherVersion":`这个镜像是固件 {image}；相机运行的是 {camera}。`,"imageBuild.otherVersionTaken":`这个镜像是固件 {image}；相机运行的是 {camera}。在这条固件线上，相机只检查镜像格式是否正确（头部和字累加和），不检查版本，所以它会接受这个镜像，并且从这个槽位启动时运行的就是 {image}。`,"imageBuild.otherVersionUnchecked":`这个镜像是固件 {image}；相机运行的是 {camera}。这台相机是否接受并运行不同的版本，尚未检查过。`,"imageBuild.otherBuild":`这个镜像是 8 Hz {version} 版本；相机运行的是 16 Hz {version} FF 版本。16 Hz 版本在提交载荷时会按自己的 FF 形式检查它，并在擦除槽位之前拒绝不符合的载荷（依据其源代码）。尚未在相机上试过向它写入 8 Hz 版本。`,"imageBuild.runningUnknown":`这个镜像是 8 Hz {version} 版本。相机运行的是 {version}，它有 8 Hz 和 16 Hz FF 两个版本，而相机自己的应答没有表明它运行的是哪一个，因此无法判断这是否就是它的版本。`,"bootFail.tooShort":`载荷为 {size} B，太短，无法在 0x200 处容纳头部`,"bootFail.noMagic":`0x200 处没有镜像魔数（找到的是 {found}，引导程序需要 {needs}）`,"bootFail.lengthOutside":`header.length {length} 超出了 {size} B 的载荷`,"bootFail.lengthNotPayload":`header.length {length} 不等于载荷长度 {size}`,"bootFail.overStage":`{size} B 超过了 {max} B 的暂存区`,"bootFail.plainSum":`存储的字累加和为 {sum}，2014 年的引导程序要求为 0`,"bootFail.noFooter":`{offset} 处没有尾部：载荷在 {end} 处结束`,"bootFail.footerNotCode":`{offset} 处的尾部不是“CODE”——引导程序会采用其分段加载器`,"bootFail.footerLength":`尾部长度不等于 header.length {length}`,"bootFail.keyASum":`用这台相机的密钥 A 解密后，字累加和为 {sum}，引导程序需要 {needs}`,"keyConfidence.family":`已通过校验和验证`,"keyConfidence.structural":`仅通过向量表验证`,"keyConfidence.unverified":`未验证`,"keyCheck.family":`密钥已通过校验和 {sum} 验证`,"keyCheck.other":`密钥{phrase}；校验和 {sum}`,"staging.phrase.keyACiphertext":`按相机自身的密钥暂存`,"staging.phrase.slotKeystreamCiphertext":`按镜像自身的密钥暂存`,"staging.phrase.plain":`以明文暂存`,"staging.phrase.keyAKeystream":`按厂商应用暂存 FF 镜像的方式暂存（XOR 密钥 A）`,"staging.phrase.verbatim":`按给定内容发送`,"written.committed":`已向{name}（{address}）提交 {size} B，{staged}；提交状态 {status}`,"written.noReadWindow":`此版本没有为该槽位指定读取窗口，因此没有回读任何内容`,"written.readBackFailed":`回读失败：{error}`,"written.readBack":`已回读 {size} B，SHA-256 {sha256}`,"written.verifyOff":`验证已关闭：没有回读该槽位`,"readBack.reference.folded":`计划预测该槽位会存放的字节（16 Hz 版本存储的镜像形式，而不是发送的字节）`,"readBack.reference.asSent":`计划预测该槽位会存放的字节（即发送的字节）`,"readBack.sizeDiffers":`回读结果为 {size} B，计划预测为 {predictedSize} B：该槽位与{reference}并不一致`,"readBack.matchesFolded":`该槽位存放的是 16 Hz 版本存储形式的镜像（而不是发送的字节），槽位的其余部分已擦除`,"readBack.matches":`该槽位与计划预测的字节一致（2014 年的明文链写入的正是它收到的内容）`,"readBack.differs":`该槽位与{reference}并不一致（第一处差异在 {offset}）`,"readBack.noHeader":`回读结果在 {offset} 处没有镜像头部（魔数 {magic}），因此该槽位解密后并不是预期的镜像`,"readBack.lengthDiffers":`回读结果的头部表明长度为 {length} B，而计划中的镜像为 {imageLength} B：该槽位解密后并不是预期的镜像`,"readBack.tooShort":`回读结果为 {size} B，对 {length} B 的镜像来说太短：该槽位解密后并不是预期的镜像`,"readBack.recovered":`从回读结果中恢复的密钥流（{check}）`,"readBack.decrypts":`使用{recovered}，该槽位解密后正是预期的镜像（{length} B）`,"readBack.decryptDiffers":`使用{recovered}，该槽位解密后并不是预期的镜像：第一处差异在镜像偏移 {offset}`,"readBack.rawNotCompared":`原始字节：已报告回读结果，但没有比对（这些字节在这种形式下不能解密为可预测的明文镜像，而且设备会重新加密它保存的内容）`,"readBack.notCompared":`无法比对：计划既无法预测存储的字节，也无法预测明文镜像`,"keyName.keyA":`密钥 A`,"keyName.keyB":`密钥 B`,"keyName.perDevice":`设备专属密钥`,"keyName.thePerDevice":`该设备专属密钥`,"keyName.applicationKeyA":`应用程序的密钥 A`,"keyName.applicationKeyB":`应用程序的密钥 B`,"keyName.block1":`密钥块 1`,"keyName.theDeviceKey":`设备密钥`,"keyName.unknown":`未知密钥`,"keys.noKnownKey":`没有已知密钥`,"keys.evidence.plainChain":`2014 年的明文链：每个槽位都以明文存储，因此不推导上传密钥；上传的就是镜像本身`,"keys.evidence.ffVendor":`1.3.0.8 FF（16 Hz）版本：本次读取打开的槽位都不是以明文存储的，因此不能表明相机属于 2014 年的明文链；FF 镜像以厂商形式写入，原始字节按给定内容发送，不会写入 8 Hz 明文镜像`,"keys.evidence.ffUntested":`提供 FF 镜像的写入，但附有 UNTESTED（未经测试）警告：资料库中没有这个版本的真实引导程序，因此写入的槽位能否启动尚未测得`,"keys.evidence.line2016":`2016 年的 Compact PRO 固件线：上传的数据是镜像与其自身密钥块 0（按值在镜像中找到）的密钥流异或的结果，因此不需要这台相机的任何密钥来构造`,"keys.evidence.checkKeyUnnamed":`相机用该密钥解密上传的数据，再以其引导程序检查槽位时使用的密钥重新加密；本次读取没有指明那个密钥，而写入也不需要它：会按槽位解密后的镜像来回读检查`,"keys.evidence.checkKeyUnnamedWhy":`相机用该密钥解密上传的数据，再以其引导程序检查槽位时使用的密钥重新加密；本次读取没有指明那个密钥（{why}），而写入也不需要它：会按槽位解密后的镜像来回读检查`,"keys.evidence.checkKeyNamed":`相机用该密钥解密上传的数据，再以{key} {hex}（其引导程序检查槽位时使用的密钥）重新加密，因此它写入的每个槽位都以引导程序接受的方式存储`,"keys.evidence.checkKeyInferred":`相机用该密钥解密上传的数据，再以{key} {hex}（其引导程序检查槽位时使用的密钥，是从{bank} 推断得出的——相机报告它进入了该槽位，而引导程序进入它时没有检查）重新加密，因此它写入的每个槽位都以引导程序接受的方式存储`,"keys.evidence.checkKeyNamedFrom":`相机用该密钥解密上传的数据，再以{key} {hex}（其引导程序检查槽位时使用的密钥，根据相机报告它进入的{bank} 指明）重新加密，因此它写入的每个槽位都以引导程序接受的方式存储`,"keys.evidence.applicationKeyA":`正在运行的应用程序（{bank}，固件 {firmware}）在 {keyAAt} 处带有它的密钥 A {keyA}，来自{source}`,"keys.evidence.applicationKeys":`正在运行的应用程序（{bank}，固件 {firmware}）在 {keyAAt} 处带有它的密钥 A {keyA}，来自{source}，并在 {keyBAt} 处带有它的密钥 B {keyB}`,"keys.source.keyTable":`引导程序的密钥表`,"keys.source.applicationPair":`{builds} 的已解码应用程序密钥对`,"keys.evidence.perDevice":`已烧录设备专属密钥，因此应用程序会以它重新加密`,"keys.evidence.noPerDevice":`没有烧录设备专属密钥，因此应用程序会以它自己的密钥 B 重新加密`,"keys.evidence.storeKey":`应用程序的存储密钥就是引导程序的{key}（{hex}），因此写入时每个槽位都以它存储；当前启动的{bank} 持有{held}，引导程序同样接受`,"keys.evidence.bootedKey":`当前启动的{bank} 可用{key}（{hex}）解密，这是引导程序会尝试的密钥；应用程序的存储密钥不是引导程序的密钥，因此写入时每个槽位都以当前启动槽位的密钥存储`,"keys.evidence.masks":`上传的数据是镜像与{masks} 的密钥流异或的结果；设备以{key} 存储镜像`,"keys.evidence.otherBank":`{bank} 可用{held} 解密；按同样的规则，它以{key} 写入，并回读检查`,"keys.refused.bootUnnamed":`无法确定当前启动的槽位，因此无法从中读出槽位存储所用的密钥`,"keys.refused.notDerived":`无法推导出密钥`,"keys.refused.notDecrypted":`当前启动的{bank} 无法解密为镜像，因此无法读出它存储所用的密钥`,"keys.refused.noBootKey":`当前启动的{bank} 无法用引导程序会尝试的任何密钥（它的密钥 A 或存储密钥）解密，因此无法从中读出槽位存储所用的密钥`,"keys.refused.keyNotInTable":`当前启动的{bank} 可用{key} 解密，但这台相机的密钥表中没有该密钥，因此无法以它写入`,"keys.refused.noApplicationPair":`正在运行的应用程序（{bank}，固件 {firmware}）中没有任何已知密钥对（引导程序的密钥对和已解码的应用程序密钥对）是两半各恰好出现一次的，因此无法在其镜像中定位它的密钥 A`,"keys.refused.noApplicationPairCounted":{other:`正在运行的应用程序（{bank}，固件 {firmware}）中没有任何已知密钥对（引导程序的密钥对和已解码的应用程序密钥对）是两半各恰好出现一次的，因此无法在其镜像中定位它的密钥 A（引导程序的密钥 A 出现 {count} 次，密钥 B 出现 {keyB} 次）`},"keys.refused.uploadChecked":`正在运行的应用程序（{bank}，固件 {firmware}）在写入上传的数据之前会用自己的密钥检查它（这个版本解码后的源代码会用它的密钥 A 和存储密钥尝试上传的数据，就像其引导程序检查槽位一样），而写入所用的存储密钥{key}（{hex}）既不是它的密钥 A，也不是它的存储密钥，因此相机会在擦除任何内容之前以 0x50000 拒绝这次上传`,"writeRefusal.acceptanceSum":`没有任何槽位解密后得到 {family} 的校验和 {sum}`,"writeRefusal.keyTable":`无法确认这台相机的密钥表`,"writeRefusal.whitening":`这台相机的密钥表在 K={k} 下解析，但 {family} 在 K={expected} 下加密`,"writeRefusal.otherFamily":`证据表明这台相机是 {detected}，而不是 {family}（{reasons}）`,"writeRefusal.camera":`无法从这里写入这台相机：{reasons}`,"family.summary.modern":`Seek 2018 年及以后的版本（2.x、4.x、10.x、42.x、44.x）：Compact 4.8/4.16、Compact Pro 4.9/4.18、Compact Pro FF、Compact XR、Mosaic 2.27/10.9、Nano 200 和 Nano 300。导出无需任何解锁即可读取闪存 64 个块中的 63 个；在这些版本上，任何读取都无法访问 {block} 处的块。固件以加密形式存储。在“固件槽位操作”标签页上一次写入一个槽位。`,"family.summary.early":`早于 0.8.0.0 的 2014 年 Compact：0.3.0.1、0.5.0.2、0.5.1.0、0.5.1.3、0.6.0.4、0.7.0.7 和 0.7.0.8。它们的固件无法应答导出发送的读取命令，因此“导出”、“导出全部选择器”、“信息”标签页的完整读取以及“固件槽位操作”标签页会在读取版本后拒绝它们；在 0.3.0.1 上，导出开头发送的命令反而会启动一次固件升级。0.x/1.x 标签页的完整备份流程会通过这两个版本能应答的另一个命令读取 0.7.0.7 和 0.7.0.8。用其他方式导出的镜像照常可以解密。`,"family.summary.compact2016":`Compact PRO 1.0.3.x 版本（1.0.3.0 和 1.0.3.2）。它们应答读取的方式与 2014 年的 Compact 完全相同，包括解锁令牌，因此要靠版本号和槽位的存储方式来区分：它们是加密存储的，而 2014 年的槽位是明文。1.0.3.x 相机从一开始就按这个固件系列读取。0.x/1.x 标签页的完整备份流程会读取整片闪存，槽位在“固件槽位操作”标签页上一次写入一个。`,"family.summary.legacy":`0.8.0.0 到 1.3.0.8 的 2014 年 Compact，包括 16 Hz 的 1.3.0.8 FF 版本。原厂相机只允许读出不到一半的闪存，其中一部分还需要本工具箱发送解锁令牌才能读出；0.x/1.x 标签页的完整备份流程会通过一个临时补丁读取其余部分。除 FF 版本外，槽位都以明文存储。Compact PRO 1.0.3.x 相机按 compact-2016 读取，只有当某个槽位以明文存储或解密后得到 {sum}（就像 FF 版本的槽位那样）时，才会归到这里。在完整备份流程测量过的版本上，可以在“固件槽位操作”标签页上写入槽位；其他 0.x 或 1.x 版本只能读取。`,"family.summary.generic":"不符合任何其他固件系列的相机。`seek-fw dump` 会用 4.x 的块列表读取它（4.x/Nano 标签页会拒绝它），解密则从镜像本身求出密钥，所以两者都不依赖这个猜测。不会写入任何槽位：在识别出相机之前，“固件槽位操作”标签页会拒绝它。","detect.source.header":`镜像头部表明`,"detect.source.camera":`相机报告`,"detect.plainArmedNotInForce":`一个普通的 2 字节 BeginFirmwareUpgrade 打开了受保护的槽位，因此认证读取通道并未生效`,"detect.modern.plainRefused":`一个对受保护槽位的普通 2 字节 BeginFirmwareUpgrade 被拒绝了，而这条固件线上没有任何版本会这样做——它的处理程序没有令牌检查，在每个槽位上都接受普通通道`,"detect.modern.authArmed":`一个受保护的槽位在 18 字节的认证选择器上被打开；那里没有尝试普通选择器，所以这并不能把这台相机排除在这条固件线之外`,"detect.modern.legacyVersion":`{said}固件 {version}，它属于 0.x / 1.x 旧固件线（这是另一套编号，不是更早的 4.x——而且其中一个版本也会得到 {sum} 这个和值）`,"detect.modern.noSum":`没有任何槽位解密后得到该固件系列引导程序要求的校验和 {sum}`,"detect.modern.sum":`有槽位解密后得到校验和 {sum}`,"detect.modern.version":`固件 {version} 属于这个选择器映射适用的 2018 年后固件线（2.x / 4.x / 10.x / 42.x / 44.x：Compact、Compact Pro、Compact XR、Mosaic、Nano）`,"detect.modern.plainWorks":`一个普通的 2 字节 BeginFirmwareUpgrade 打开了受保护的槽位，因此这不是加锁的旧固件`,"detect.modern.none":`没有证据表明这台相机属于 2018 年后的固件线`,"detect.early.noVersion":`没有报告固件版本，镜像头部中也没有找到`,"detect.early.readable":`固件 {version} 为 {first} 或更新的版本，因此它的 RPC 表中有 GetFeaturedFirmwareData 的读取处理程序（getter），可以走普通读取路径`,"detect.early.older":`{said}固件 {version}，早于 {first}——这是第一个在 RPC 方法表中带有 GetFeaturedFirmwareData 读取处理程序（getter）的版本`,"detect.early.noWindow":`而且无法读取任何窗口，这正符合上述推断`,"detect.generic.fallback":`后备：没有固件系列能可靠匹配，因此仍可读取，但不能写入`,"detect.compact2016.early":`固件 {version} 早于 0.8.0.0，没有 GetFeaturedFirmwareData 的读取处理程序——那是 early-compact，不是这个固件系列`,"detect.compact2016.modernSum":`有槽位解密后得到校验和 {sum}，这不是这一代的目标值`,"detect.compact2016.plainArmed":`一个普通的 2 字节 BeginFirmwareUpgrade 打开了受保护的槽位，因此这台相机不在这个固件系列与 legacy-auth 共用的加锁固件线上`,"detect.compact2016.notLine":`固件 {version} 不属于 0.x / 1.x 固件线`,"detect.compact2016.storedPlain":`有槽位以明文存储——密钥流求解得到的是恒等状态，所以它存储的字就是镜像本身——这是 2014 年的明文链；这一代的槽位是用真实密钥进行 xorshift128 加密的`,"detect.compact2016.keyedZero":`一个以真实 xorshift128 密钥流存储的槽位解密后得到校验和 {sum}，这正是这一代的加密方式`,"detect.compact2016.zeroSum":`有槽位解密后得到校验和 {sum}，这正是这一代的目标值`,"detect.compact2016.refused":`而且受保护的槽位拒绝了普通的 2 字节打开请求，这是加锁的处理程序`,"detect.compact2016.proLine":`{said}固件 {version}，属于 2016 年 Compact PRO 的 1.0.3.x 固件线`,"detect.compact2016.compactLine":`{said}固件 {version}，这是 Compact 的版本，不属于 Compact PRO 的 1.0.3.x 固件线`,"detect.compact2016.lockedLine":`{said}固件 {version}，属于这一代与加锁的旧固件共用的 0.x / 1.x 固件线`,"detect.compact2016.bootloader2016":`引导程序报告 {version}，这是 2016 年一代的引导程序（1.2.0.0 是在 Compact PRO 1.0.3.0 上测得的；2014 年 Compact 的是 0.9.0.0）`,"detect.compact2016.bootloader2014":`引导程序报告 {version}，这是 2014 年一代的编号，而不是这一代的`,"detect.compact2016.none":`没有观察到任何槽位在真实密钥下解密得到为零的校验和`,"detect.legacy.proLine":`但固件 {version} 属于 2016 年 Compact PRO 的 1.0.3.x 固件线，其槽位使用 compact-2016 的加密方式：这个固件系列的校验会让它们全部不通过`,"detect.legacy.early":`固件 {version} 早于 0.8.0.0：它的 RPC 表中没有 GetFeaturedFirmwareData 的读取处理程序（0.7.0.7 之前完全没有，0.7.0.7 和 0.7.0.8 上只有 setter）——那是 early-compact，不是这个固件系列`,"detect.legacy.keyedZero":`一个以真实 xorshift128 密钥流存储的槽位解密后得到 {zero}——这是 2016 年 Compact PRO 的加密方式（compact-2016）。这条固件线的槽位要么以明文存储、字累加和为 0（2014 年的明文链），要么加密后和值为 {sum}（Compact 1.3.0.8），这样的槽位无法通过它的校验`,"detect.legacy.plainChain":`有槽位以明文固件存储，其字累加和为 0，正如这条固件线的 2014 年引导程序启动它的方式`,"detect.legacy.refused":`在没有解锁的情况下请求为升级打开加锁的槽位时，相机拒绝了，而只有这一代固件会这样做`,"detect.legacy.unlocked":`而在带解锁请求时，它打开了同一个槽位，所以这个固件系列发送的解锁正是这台相机检查的那一个`,"detect.legacy.notLine":`{said}固件 {version}，它不属于 0.x / 1.x 旧固件线`,"detect.legacy.authOnly":`在带解锁请求时，它为升级打开了加锁的槽位，这一代固件正是如此；没有尝试不带解锁的请求，所以仅凭这一点无法证明是这一代`,"detect.legacy.version":`固件 {version} 属于 0.x / 1.x 旧固件线，这与 2018 年后的应用程序版本是不同的编号体系，并不是更早的 4.x`,"detect.legacy.none":`没有观察到任何迹象指向认证读取通道`,"fps.table.withheld":`在一台相机上运行后暂不提供：在那台相机上，补丁没有提高发布帧率，而且写入后每一帧都会触发快门`,"fps.table.predates":`固件 {version} 早于 0.8.0.0：它的 RPC 表中没有 GetFeaturedFirmwareData（槽位读取发送的命令）的读取处理程序，因此槽位功能不会读取或写入这个版本的任何槽位，也不提供补丁`,"fps.table.stageTwoFf":`stage two：16 Hz FF 版本按厂商应用的方式暂存（镜像 XOR 密钥 A，以密钥 B 存储），而不是以明文字节暂存，因此它的暂存检查尚未完成，暂不提供补丁`,"fps.table.stageTwo":`stage two：这个条目不在 stage two 集合中，因此它的暂存检查尚未完成，暂不提供补丁`,"fps.table.notOffered":`不提供`,"fps.table.notImage":`这不是固件镜像，因此不适用任何帧率补丁`,"fps.table.otherBuild":`镜像是 {image} 版本（“{id}”），但相机报告的是 {camera}；补丁不会应用到与它不匹配的版本上，因此被拒绝`,"fps.table.otherBuildNoVersion":`镜像是 {image} 版本（“{id}”），但相机没有报告版本；补丁不会应用到与它不匹配的版本上，因此被拒绝`,"fps.table.patched":`帧率补丁已经应用：此镜像以 {hz} Hz 运行`,"fps.table.earlierPatch":`此镜像带有较早的、不含 USB 修复的 {hz} Hz 帧率补丁，而补丁绝不会应用到已打过补丁的镜像上：请先还原原厂镜像，再打补丁`,"fps.table.atRate":`此版本不打补丁就已经以 {hz} Hz 运行`,"fps.table.not4821":`此镜像报告为 Compact 4.8.2.1 版本（或 Compact XR 4.8.2.1，同一个版本），但它不是帧率补丁所针对的原厂镜像（f96ac57eda75：68 字节的命令页，稳定页 13），因此不会为它制作帧率补丁`,"fps.table.notInTable":`此镜像不在帧率补丁表中，因此不会为这个版本制作帧率补丁。该表列出的是 Compact 0.7.0.8 到 1.3.0.8（8 Hz；0.7.0.8 会被槽位功能的代码拒绝）、1.3.0.8（16 Hz FF）、4.8.1.7、4.8.1.9、4.8.2.1 和 4.16.1.7 FF 版本，以及 Compact PRO 1.0.3.x 和 4.9.x 版本；其他版本都没有条目`,"fps.plan.noBank":`此版本的计划中没有{bank}`,"fps.plan.noPlain":`在此版本上，{bank} 不能接受解密后的镜像：{reason}`,"fps.plan.empty":`{bank} 中没有可修补的解密镜像（它是空的）`,"fps.plan.noImage":`{bank} 中没有可修补的解密镜像（它没有被读取，或者没有密钥能打开它）`,"fpsEvery.stopped.readBack":`{name} 已写入，但它的回读结果与保存的槽位相比，差异不只是计划中的那些，因此其后的槽位都没有写入`,"fpsEvery.stopped.error":`{name}：{error}`,"notes.lockedBootWord":`在这条固件线上，所说的当前启动槽位是相机上次启动时进入的槽位，按活动槽位字的记录（0 为槽位 A，1 为槽位 B，2 为恢复槽位 R）。下次启动由启动配置字决定：0 或 0xFFFFFFFF 先选 A，1 先选 B，其他任何值先选恢复槽位 R。只要 A 和 B 中都没有 2014 年引导程序接受的内容（字累加和为 0 的槽位），无论 R 中存放的是什么，都会运行恢复槽位 R（已在相机上测得）。`,"notes.locked2016BootWord":`在这条固件线上，所说的当前启动槽位是相机上次启动时进入的槽位，由引导程序记录在活动槽位字中（0 为槽位 A，1 为槽位 B，2 为恢复槽位 R）。下次启动由启动配置字决定：0 或 0xFFFFFFFF 先选 A，1 先选 B，其他任何值先选恢复槽位 R。2016 年的引导程序只有在槽位用它检查槽位的密钥（其 1.2.0.0 引导程序上为密钥块 1）解密后字累加和为 0 时才接受该槽位；当另外两个都不通过时，该顺序中的最后一个槽位会不经检查直接运行。由于存放该密钥的引导程序块在所有通道上都被拒绝读取，本次读取根据相机进入的槽位来指明该密钥（已在相机上测得）。`,"notes.ep0of1032":`1.0.3.2：EP0 会话在大约 64 到 81 KB 时中断，128 B 是无损读取单位，因此每个会话读取一个 64 KB 槽位是测得的上限。这个版本拒绝整片闪存读取（PRESERVATION.md：不存在单次打开的整片读取）。槽位导出一次读取一个槽位，每次请求 64 字节。`,"notes.token":`这条固件线上的槽位是加锁的：只有在请求附带该固件线的解锁时，相机才会为写入打开槽位；在已记录的这条固件线的全部 22 个固件镜像中，这个解锁都相同。使用其他解锁的相机会拒绝打开它的槽位。`,"notes.staging.lockedPlain":`暂存：镜像本身，最多 56 KB（相机一次写入最多接受的大小）。写入会擦除 64 KB 槽位并准确写入这些字节，槽位的其余部分读出为已擦除状态。引导程序只有在槽位的字累加和为 0 时才会启动它，所以镜像在发送之前会被平衡到这个和值。`,"notes.staging.locked2016":`暂存：镜像与其自身密钥块 0（暂存密钥，按值在镜像中找到）的 xorshift128 密钥流异或，仅为镜像长度（最多 0xE000 字节）。设备用该密钥解密载荷，再以其引导程序检查槽位时使用的密钥（密钥块 1）存储，因此存储的字节与暂存的字节不同。暂存时不会从目标槽位读取任何内容：该槽位的密钥流只用于回读槽位。`,"notes.staging.modern":`暂存：整个 64 KB 槽位，即镜像 + 0xFF 填充 + “CODE”尾部。镜像会与特定的密钥流异或，使正在运行的应用程序自己的两轮处理最终以当前启动槽位持有的密钥存储它：当提交命令（CompleteMemoryUpgrade）收到数据类型 7、8 或 9 时，应用程序用它的密钥 A 解密上传的数据，再以它的存储密钥重新加密并写入槽位。正是尾部让引导程序接受该槽位，所以缺少尾部的槽位会被拒绝。`,"notes.modernGap":`在这条固件线上，槽位 B 位于 0x14050000（模式 8）。在任何 2.x、4.x、10.x、42.x 或 44.x 版本上，都没有选择器能访问 0x14060000（根据 14 个 2018 年后的资料库镜像解码得出），所以那里没有槽位。0x14060000 的布局属于加锁的 0.x/1.x 固件线。`,"notes.modernNamedWrite":`命名写入（模式 7 到 9）是从固件中解码出来的。模拟器在 4.x 版本上通过它们写入 A、B 和 R；在相机上，帧率补丁曾通过模式 7 写入一台 Compact XR 4.8.2.1 的槽位 A。槽位写入绝不会打开模式 0，即升级目标。`,"notes.unverified":`只读。槽位布局采用加锁固件线的已解码表，但还没有为这个版本测得任何暂存形式，所以不规划任何写入。`,"notes.empty.plain":`空槽位接受镜像的方式与已用槽位完全相同。明文链按原样暂存镜像字节，不使用密钥，提交时会先擦除该块，所以不会从目标槽位读取任何内容。已在一台 Compact 上测得：写入空槽位 B 的镜像回读结果完全相同，并且仅凭 B 就能启动。`,"notes.empty.modern":`空槽位接受镜像的方式与已用槽位完全相同。载荷使用由当前启动槽位和正在运行的应用程序推导出的密钥加密，而不是由目标槽位推导，设备会重新加密它，并在不读取的情况下擦除该块。尾部从存有有效尾部的槽位复制，否则构造一个空白尾部。已在模拟器上证实；尚未在相机上测得。`,"notes.empty.locked2016":`空槽位接受镜像的方式与已用槽位完全相同。暂存密钥是镜像自身密钥对中的密钥块 0，而不是从目标槽位读取的密钥；设备用它解密载荷，以自己的密钥存储，并在不读取的情况下擦除该块。已在模拟器上证实；尚未在相机上测得。`,"notes.mode2of080":`0.8.0.0：在这个版本上，模式 2（0x14000000）有导致崩溃的风险，打开后的读取会越出 SRAM 范围（PRESERVATION.md）。槽位读取或写入只会打开模式 7 到 9，绝不会打开模式 2。`,"notes.keyPairs2016":`1.0.3.0 和 1.0.3.2 的 9 Hz 版本共用一对密钥，FF 版本共用另一对。版本字符串无法区分它们，所以密钥流是从槽位本身恢复的，由槽位自己的镜像决定。`,"notes.board1030":`1.0.3.0 应用程序在 Compact Pro 以外的任何主板上都会重启，所以只有槽位中带有主板补丁时，Compact 主板才能运行它。`,"notes.bank.modernA":`通过现代映射遗漏的一种槽位打开方式写入；在相机上，一台 Compact XR 4.8.2.1 曾通过它接受写入。`,"notes.bank.recovery2016":`已在一台 Compact PRO 1.0.3.0 上测得：恢复槽位 R 接受了它自己的镜像、一个改动一个字节的镜像，以及按发送原样的原始字节，每次写入都没有出错。`,"notes.bank.ff1308A":`1.3.0.8 FF（16 Hz）镜像以厂商应用发送的形式写入这里，相机会以它自己的密钥存储。2014 年的引导程序只有在槽位的字累加和为 0 时才会启动它，因此启动时会跳过这个槽位；16 Hz 版本能否从槽位 A 启动尚未测试（UNTESTED）。8 Hz 镜像按原样写入。`,"notes.bank.ff1308B":`1.3.0.8 FF（16 Hz）镜像以厂商应用发送的形式写入这里，相机会以它自己的密钥存储。2014 年的引导程序只有在槽位的字累加和为 0 时才会启动它，因此启动时会跳过这个槽位；16 Hz 版本能否从槽位 B 启动尚未测试（UNTESTED）。8 Hz 镜像按原样写入。`,"notes.bank.ff1308R":`1.3.0.8 FF（16 Hz）镜像以厂商应用发送的形式写入这里，相机会以它自己的密钥存储。0.9.0.0 引导程序按存储原样启动恢复槽位 R，不会对其解码，所以这种形式可能无法启动：尚未测试（UNTESTED），而这个镜像的较早形式曾从这里启动（已在相机上测得）。8 Hz 镜像按原样写入。`,"notes.product.4_8_2_1":`Compact 4.8.2.1 和 Compact XR 4.8.2.1（同一个镜像）：现代的 63 窗口映射；模拟器在 Compact 和 Compact XR 的完整导出上都确认了 63 个窗口中的全部 63 个。`,"notes.product.10_9_1_31":`Mosaic 320x240 10.9.1.31：现代的 63 窗口映射，在模拟器上测得每个窗口都已确认。`,"notes.product.2_27_1_33":`Mosaic 320x240 FF 2.27.1.33：现代的 63 窗口映射，在模拟器上测得每个窗口都已确认。`,"notes.product.42_32_3_10":`Nano 200 42.32.3.10：现代的 63 窗口映射，在模拟器上测得每个窗口都已确认。它的提交命令（CompleteMemoryUpgrade）没有数据类型 32 的处理程序，而通过模式 7、8 或 9 的写入从不请求该类型。`,"notes.product.44_27_3_10":`Nano 300 44.27.3.10：现代的 63 窗口映射，在模拟器上测得每个窗口都已确认。它的打开命令（BeginFirmwareUpgrade）会把超出其接受范围（0x7F）的数据类型当作错误的第一个参数拒绝，而模式 7 到 9 在该范围之内。`,"notes.ff1308":`1.3.0.8-FF（16 Hz）报告的版本号与 8 Hz 版本相同。读取时由相机来区分它们：相机会逐个槽位说明它的应用程序是否接受该槽位，而每个版本都会根据槽位预测自己的应答。FF 镜像以厂商应用发送的形式发送，相机会以它自己的密钥存储。它可以写入槽位 A、槽位 B 或恢复槽位 R。预计 8 Hz 版本会在写入任何内容之前拒绝它；当相机的应答无法区分这两个版本时，计划会说明每个版本会如何处理它。{untested}`,"identity.versionUnknown":`相机没有报告它的固件版本（{note}）；同一个命令编号并非在每个 Seek 固件上含义都相同——在 Compact 0.3.0.1 上，用于打开读取窗口的线路 ID 0x52 是 EnterBootloaderMode——因此在知道版本之前，除了 GetErrorCode、GetOperationMode 和 GetFirmwareInfo（所有版本应答方式都相同的读取）之外，不会发送任何命令`,"identity.note.startup":`GetFirmwareInfo 在间隔 {spacing} ms 的 {reads} 次读取中都没有应答（{error}），启动等待窗口为 {window} ms；仍在启动的相机会在此窗口内应答`,"identity.note.neverTwice":`在 {reads} 次读取中，GetFirmwareInfo 从未连续两次应答`,"identity.note.noAnswer":`GetFirmwareInfo 没有应答（{error}）`,"identity.note.noAnswerSome":`GetFirmwareInfo 没有应答（{error}）；{reads} 次读取中有 {answered} 次应答，但从未连续两次，因此无法把其中任何一次与之前的命令遗留选中的记录区分开`,"identity.note.tooShort":{other:`GetFirmwareInfo 只应答了 {count} 个字节，不足以构成版本号`},"identity.note.tooShortContext":{other:`GetFirmwareInfo 只应答了 {count} 个字节，不足以构成版本号；{context}`},"identity.note.otherRecord":`第一次读取应答的是另一条记录（{version}），这是之前的命令让固件信息选择器停留在那里造成的——那次读取已将其清除`,"identity.note.afterStartup":{other:`它在启动期间拒绝了 {count} 次读取之后才应答`},"identity.predates":`固件 {version} 早于导出协议：它的 RPC 方法表中没有 GetFeaturedFirmwareData 的读取处理程序（在 0.7.0.7 和 0.7.0.8 上它只注册为 setter，更早的版本中线路 ID 0x4F 是 UploadFirmwareRowSize），因此无法用它读取任何窗口；在 0.3.0.1 上，线路 ID 0x52 是 EnterBootloaderMode，而不是 BeginFirmwareUpgrade。0.x/1.x 标签页的完整备份流程改为通过线路 ID 0x58（GetFeaturedData）读取 0.7.0.7 和 0.7.0.8`,"identity.refusing":`拒绝{operation}：{reason}`,"identity.refusingNoVersion":`拒绝{operation}：{reason}。没有打开任何读写窗口。请拔下相机，再重新插上，等它完成启动后重试。`,"identity.operation.dump":`导出`,"identity.operation.dumpAll":`导出全部选择器`,"identity.operation.readInfo":`读取设备信息`,"preserve.banks.beforeBackup":`槽位要在备份读取它们之后才能选择——请先运行备份`,"preserve.banks.afterCommit":`提交一旦运行或尝试过，槽位就不能再更改：本次运行写入{banks}，还原时也只会放回这些槽位`,"preserve.banks.none":`没有槽位`,"status.written":`已写入。`,"status.read":`已读取。{of} 个槽位中有 {count} 个可读。`,"status.readRefused":`已读取，但无法从这里写入这台相机的任何槽位——请查看日志。`,"compare.field.version":`固件版本`,"compare.field.imageId":`镜像 ID`,"compare.field.initialSp":`初始 SP`,"compare.field.resetVector":`复位向量`,"compare.field.size":`大小`,"compare.field.shaExpected":`预期明文镜像的 SHA-256`,"compare.field.sha":`镜像的 SHA-256`,"compare.field.shaNotStored":`预期明文镜像的 SHA-256（无法预测存储的字节）`,"compare.field.key":`密钥`,"compare.noImage":`（无镜像）`,"compare.notImage":`（不是镜像）`,"compare.notPredicted":`（无法预测：由设备决定存储什么）`,"compare.plaintext":`无（明文）`,"boot.verdict.unsettled":`两次读取的结果不一致`,"preserve.boot.inferred":`{why}（引导程序检查槽位所用的密钥是从{bank} 推断得出的，引导程序进入该槽位时没有检查）[inferred]`,"preserve.lastStart.entered":`{bank}，按相机的记录（活动槽位字 {word}）`,"preserve.lastStart.notRead":`未知——无法读取活动槽位字`,"preserve.lastStart.noBank":`未知——活动槽位字为 {word}，它不对应任何槽位`,"preserve.nextStart.known":`{bank}——{why}`,"preserve.nextStart.unknown":`未知——{why}`,"preserve.bank.notWritten":`不写入——{reason}`,"preserve.bank.anImage":`一个镜像`,"preserve.bank.writable":`{build}——可以写入`,"preserve.bank.writablePatch":`{build}——可以写入；补丁会改变 {count} 个字节`,"preserve.bank.writableEdit":`{build}——可以写入；带有 {edit}`,"preserve.bank.writablePatchEdit":`{build}——可以写入；补丁会改变 {count} 个字节；带有 {edit}`,"preserve.choice.notRead":`备份尚未读取槽位，因此还不能选择槽位`,"preserve.choice.every":`每个存有镜像的槽位：{banks}`,"preserve.choice.everyBlocked":`无法写入每个存有镜像的槽位：{bank} 不能——{reason}`,"preserve.choice.noImage":`没有任何槽位存有本次运行可以写入的镜像`,"preserve.choice.nextStart":`{bank}，即下次启动进入的槽位：{why}`,"preserve.choice.nextStartRefused":`下次启动会进入{bank}（{why}），而本次运行无法写入它：{reason}`,"preserve.choice.everyUnknownStart":`每个存有镜像的槽位（{banks}）：不知道下次启动会进入哪个槽位（{why}）`,"preserve.choice.unknownStartRefused":`不知道下次启动会进入哪个槽位（{why}），而且{reason}；请按名称选择一个槽位`,"preserve.choice.bank":`{bank}`,"preserve.choice.bankRefused":`{bank} 无法写入：{reason}`,"preserve.choice.byName":`{banks}，即按名称选择的槽位`,"preserve.choice.warnNotPatched":`下次启动会进入{bank}（{why}），而这个选择不会修补它：重启后相机运行的是该槽位自己的镜像，所以全闪存读取会在读取任何内容之前停止。还原仍会把每个已写入的槽位放回原样。`,"preserve.choice.warnUnknownStart":`不知道下次启动会进入哪个槽位（{why}）。如果它进入的是这个选择不修补的槽位，全闪存读取会在读取任何内容之前停止。`,"preserve.build.notKnown":`尚不知道`,"preserve.build.firmware":`固件 {version}`,"preserve.stagedForm.plain":`按相机存储的原样（这台相机以未加密形式保存固件）`,"preserve.stagedForm.oneKey":`按相机存储的形式（以相机的密钥加密）`,"preserve.stagedForm.twoKeys":`按相机存储的形式（以相机的两个密钥加密）`,"preserve.restoreForm.verbatim":`每个已写入的槽位都会恢复为备份从中读出的原样字节`,"preserve.restoreForm.factoryStaged":`每个已写入的槽位都会恢复其原始固件，以相机存储的形式写入，因此槽位最终与备份读出的内容逐字节相同`,"preserve.restoreForm.none":`在此版本上无法做到：原始固件没有任何一种形式既能通过相机自身的检查、又能存回为原始字节，所以本次运行将以完整镜像结束，补丁仍保留在相机中`,"preserve.drain.notPossible":`在此版本上无法做到：打过补丁的固件无法读取整片闪存，所以本次运行无法提供完整镜像`,"preserve.drain.rotated":`相机提供的数据是轮转过的，本次运行会把它恢复为正确顺序`,"preserve.drain.hazard":`补丁避开了此版本上会导致相机崩溃的一种读取`,"preserve.drain.whole":`一次读取整个 4 MB 闪存，每次 {size} 字节`,"preserve.drain.wholeNotes":`一次读取整个 4 MB 闪存，每次 {size} 字节；{notes}`,"preserve.site.wholeFlash":`让相机的读取命令能访问整个 4 MB 闪存，而不只是前 64 KB`,"preserve.site.countPast":`让读取位置可以计数超过 64 KB，使读取不会绕回开头`,"preserve.site.keepPosition":`每次读取后前移时保留完整的读取位置`,"preserve.site.savePosition":`完整保存前移后的读取位置`,"preserve.site.clearPosition":`每次开始读取时清除完整的读取位置，使相机在全闪存读取之后仍可被读取`,"preserve.site.modeTwoGuard":`让全闪存读取像其他读取一样开始（原厂固件会拒绝它）`,"preserve.site.modeTwoIndirection":`让全闪存读取指向闪存的开头（原厂固件让它指向一个会导致相机崩溃的值）`,"preserve.site.armTail":`去掉此版本上读取开始时会让相机卡死的一个调用`,"preserve.site.other":`修改全闪存读取所需的一条指令`,"preserve.step.backup":`备份`,"preserve.step.patch":`补丁`,"preserve.step.commit":`写入`,"preserve.step.drain":`全闪存读取`,"preserve.step.restore":`还原`,"preserve.step.verify":`检查`,"preserve.stepId.patch":`补丁步骤`,"preserve.stepId.commit":`写入步骤`,"preserve.stepId.drain":`全闪存读取`,"preserve.stepId.restore":`还原`,"preserve.stepId.verify":`检查`,"preserve.result.stoppedPlanned":`{label}：按计划停止——相机启动的是{bank}，本次运行没有修补它，因此没有读取任何内容。`,"preserve.result.noReason":`没有记录原因`,"preserve.result.stopped":`{label}：已停止——{error}`,"preserve.result.writable.none":`没有任何槽位存有本次运行可以修补的固件`,"preserve.result.writable.one":`{banks} 存有本次运行可以修补的固件`,"preserve.result.writable.many":`{banks} 存有本次运行可以修补的固件`,"preserve.result.backup":`{label}：普通读取能访问的每个块都已保存；{writable}。`,"preserve.result.nextUnknown":`一个未知的槽位`,"preserve.result.backupNext":`{label}：普通读取能访问的每个块都已保存；{writable}；下次启动会进入{next}。`,"preserve.result.patch":`{label}：已为{banks} 生成。`,"preserve.result.patchNone":`{label}：未生成补丁：没有任何槽位存有本次运行可以修补的固件。`,"preserve.result.patchCount":`{label}：已为{banks} 生成；每个槽位改变 {count} 个字节。`,"preserve.result.commitOne":`{label}：已用补丁写入{banks}，相机已接受。`,"preserve.result.commitMany":`{label}：已用补丁写入{banks}，相机已逐一接受。`,"preserve.result.drainNotRead":`{label}：未读取。`,"preserve.result.drain":`{label}：已读取整个 4 MB 闪存；完整镜像的 sha256 为 {sha256}。`,"preserve.result.drainThrough":`{label}：已通过{bank} 读取整个 4 MB 闪存；完整镜像的 sha256 为 {sha256}。`,"preserve.result.restore":`{label}：已写回{banks}。`,"preserve.result.restoreForm":`{label}：已{form}写回{banks}。`,"preserve.result.verifyDone":`{label}：完成。`,"preserve.result.verifyIdentical":`{label}：重新读取了 {blocks} 个块，0 个字节不同——相机的闪存与备份逐字节相同。`,"preserve.result.verifyDiffers":`{label}：重新读取了 {blocks} 个块，有 {bytes} 个字节不同。`,"preserve.result.verifyDiffersUnread":{other:`{label}：重新读取了 {blocks} 个块，有 {bytes} 个字节不同，{count} 个块无法读取。`},"preserve.unpatchedStart.stop":`在全闪存读取之前停止：相机启动的是本次运行没有修补的槽位，因此没有读取任何内容。`,"preserve.unpatchedStart.next":`下一步：还原会把每个已写入的槽位放回原样。不会再次尝试全闪存读取：相机仍会启动同一个槽位。`,"preserve.done.title":`完成——你的固件已完整保存`,"preserve.done.detail":`完整镜像就是相机原始的整片闪存，而相机本身也已完全恢复原样。`,"preserve.done.titleNoImage":`完成——相机已恢复原样；没有完整镜像`,"preserve.done.detailNoImage":`全闪存读取没有运行，因此本次运行没有闪存的完整镜像。每个已写入的槽位都已放回原样，重新读取普通导出能访问的块，结果与备份一致。要获得完整镜像，请开始一次新的运行，并选择包含下次启动进入的那个槽位。`,"preserve.done.detailNoImageCount":`全闪存读取没有运行，因此本次运行没有闪存的完整镜像。每个已写入的槽位都已放回原样，重新读取普通导出能访问的 {blocks} 个块，结果与备份一致。要获得完整镜像，请开始一次新的运行，并选择包含下次启动进入的那个槽位。`,"preserve.fail.spentReader":"相机的窗口读取功能每次启动只有有限的额度，这些读取返回时额度已经用尽——请给相机断电重启（拔下再重新插上，或使用它的电源开关），然后重新运行 `preserve --resume <run-directory>`。特征：{signature}","preserve.fail.spentReaderDerive":"相机的窗口读取功能每次启动只有有限的额度，这些读取返回时额度已经用尽——请给相机断电重启（拔下再重新插上，或使用它的电源开关），然后重新运行 `preserve --resume <run-directory>`。特征：{signature}——无法从这些字节推导出原厂明文。已尝试所有读取方式：\n  - {reasons}","preserve.fail.notInBackup":`备份中没有{bank}（{address}）——原厂读取窗口无法提供它`,"preserve.fail.readsDisagree":`对{bank} 的两次读取不一致（sha256 {sha256} 与 {other}）——无法连续两次一致地提供它正在运行的槽位的相机，不是可以写入的相机；采集数据既是还原的来源，也是推导补丁的输入`,"preserve.fail.notFactory":`{bank} 中不是按此版本加密方式存储的原厂镜像（预期的镜像前缀与采集数据不符）——在记录任何内容之前就拒绝，更不用说写入`,"preserve.fail.ffSum":`打过补丁的固件以相机存储的形式无法通过此版本自身的检查（其和值必须为 {sum}）——拒绝发送一个相机会在擦除后拒收的槽位`,"preserve.fail.headChanged":`{bank} 的开头部分自备份以来已经改变（既不是原始采集数据，也不是打过补丁的字节）——拒绝覆盖状态未知的槽位；没有写入任何内容。开头部分十六进制：当前 {live}，采集 {capture}`,"preserve.fail.landedOne":`{banks} 中已经是打过补丁的字节——提交已在之前的尝试中完成，不能再次执行。请从全闪存读取步骤继续（--resume），它会启动打过补丁的镜像并从那里继续。`,"preserve.fail.landed":`{banks} 中已经是打过补丁的字节——提交已在之前的尝试中完成，不能再次执行。请从全闪存读取步骤继续（--resume），它会启动打过补丁的镜像并从那里继续。`,"preserve.fail.drainRebootRefused":`全闪存读取的重启命令在发出之前就被主机拒绝了（SecurityError：浏览器策略或测试防护），因此相机仍在运行它启动时的镜像，而不是已提交的补丁。全闪存读取只能通过打过补丁的镜像所扩大的窗口进行，所以它在打开任何读写窗口之前就停止了；没有读取任何内容。请在主机允许重启命令通过的环境中再次运行全闪存读取。`,"preserve.fail.shiftedRebootRefused":`全闪存读取返回的数据偏高了一页，而用于再启动一次的重启命令在发出之前就被主机拒绝了（SecurityError：浏览器策略或测试防护）——再试一次也只会读取同样偏移的启动。没有保留任何内容；请在重置命令能够发出的环境中再次运行全闪存读取。`,"preserve.fail.verify":{other:`验证读取在 {read}/{total} 个窗口中发现 {count} 个不同字节——芯片重新读取的结果与备份并不逐字节相同`},"preserve.fail.verifyIn":{other:`验证读取在 {read}/{total} 个窗口中发现 {count} 个不同字节（位于 {places}）——芯片重新读取的结果与备份并不逐字节相同`},"preserve.fail.verifyShort":{other:`验证读取在 {read}/{total} 个窗口中发现 {count} 个不同字节（不完整的窗口：{short}）——芯片重新读取的结果与备份并不逐字节相同`},"preserve.fail.verifyInShort":{other:`验证读取在 {read}/{total} 个窗口中发现 {count} 个不同字节（位于 {places}）（不完整的窗口：{short}）——芯片重新读取的结果与备份并不逐字节相同`},"preserve.fail.verifyPlace":`{what} {address}`,"preserve.fail.bootConfigBlock":`启动配置块`,"preserve.fail.dataBlock":`一个数据块`,"preserve.refused.secondRead":`它的第二次读取失败（{error}）`,"preserve.refused.readsDisagree":`它的两次读取不一致（sha256 {sha256} 与 {other}）`,"preserve.refused.erased":`它已被擦除`,"preserve.refused.watchdogMark":`它在 +0x200 处的头部字为 {word}，这是启动早期看门狗复位后引导程序写在槽位上的标记；引导程序不再接受这个槽位，本次运行在那里没有可修补的镜像`,"preserve.refused.noHeader":`它在 +0x200 处没有镜像头部`,"preserve.refused.otherBuild":`它存放的是 {image}（{id}），而不是相机运行的版本（{camera}）`,"preserve.refused.otherKey":`引导程序的检查会拒绝它：它是以另一个密钥存储的，而不是这台相机的引导程序检查槽位时使用的密钥；通过相机写入会以那个密钥存储它，因此还原无法放回它的原样字节`,"preserve.error.otherVersion":`相机报告的固件是 {camera}，需要的是 {version}——补丁是从一个版本的字节推导出来的，绝不能发送给另一个版本`,"preserve.refused.outsideLine":`固件 {version} 不是 0.x 或 1.x 版本，而本次运行只适用于 2014 年和 2016 年的版本。除版本外没有读取任何内容。请改用“导出并解密 4.x/Nano”读取这台相机：它无需补丁即可读取闪存中除 0x14060000 处之外的每个块，在这些版本上没有任何读取窗口能访问那个块。`,"preserve.refused.preWidening":`固件 {version} 早于扩大读取范围的方法，本次运行宁可拒绝，也不覆盖一个它无法回读的槽位。在这一代上，相机会拒绝该方法所需的每一种启动读取的方式（在 0.3.0.1 上测得），它的读取命令无法访问闪存的开头，而补丁要修改的大小也以不同的方式存储。它也没有标准导出可以使用的读取。除版本外没有读取任何内容。`,"preserve.image.unknown":`存放着未知的镜像（既不是原厂 {version} 固件，也不是 Preserve 认识的对它的修改），因此 Preserve 不会修补它，也不会把它放回`,"preserve.image.frameRate":`存放着已知的帧率版本：带有 {hz} Hz 帧率补丁的原厂 {version} 固件。Preserve 只修补原厂固件，绝不修补打过补丁的镜像，因此不会修补这个槽位，也不会把它放回`,"preserve.image.frameRateEarlier":`存放着已知的帧率版本：带有较早的 {hz} Hz 帧率补丁（在加入 USB 修复之前制作）的原厂 {version} 固件。Preserve 只修补原厂固件，绝不修补打过补丁的镜像，因此不会修补这个槽位，也不会把它放回`,"preserve.image.unknownWords":`它{what}。要包含这个槽位，请先把原厂镜像写回其中（例如从修改之前做的完整闪存备份中），然后开始一次新的运行`,"preserve.image.frameRateWords":`它{what}。要包含这个槽位，请先把原厂镜像写回其中（例如从打帧率补丁之前做的完整闪存备份中），然后开始一次新的运行；之后可以在原厂镜像上重新打帧率补丁`,"preserve.image.unknownRefusal":`{name} {what}。本次运行要从这个槽位获取它所修补的固件，所以在写入任何内容之前就在这里停止。要完整保存这台相机，请先把原厂镜像写回{bank}（例如从修改之前做的完整闪存备份中），然后开始一次新的运行。`,"preserve.image.frameRateRefusal":`{name} {what}。本次运行要从这个槽位获取它所修补的固件，所以在写入任何内容之前就在这里停止。要完整保存这台相机，请先把原厂镜像写回{bank}（例如从打帧率补丁之前做的完整闪存备份中），然后开始一次新的运行；之后可以在原厂镜像上重新打帧率补丁。`,"preserve.image.otherFirmware":`它存放的是固件 {image}，而不是相机运行的 {camera}`,"preserve.image.otherFirmwareRefusal":`{name} 存放的是固件 {image}，而不是相机运行的 {camera}，因此本次运行在那里没有可修补的镜像，宁可拒绝也不覆盖它。`,"preserve.image.noImage":`无法从中推导出本次运行可以修补的镜像（{error}）`,"preserve.gate.runDone":`本次运行已完成——所有步骤都已完成（运行 {run}）`,"preserve.gate.stepDone":`{step} 在本次运行中已经完成（完成于 {finished}）——继续运行将从 {next} 开始`,"preserve.gate.stepDoneUnknownTime":`{step} 在本次运行中已经完成（完成时间未知）——继续运行将从 {next} 开始`,"preserve.gate.backupRerun":`备份不能重新运行：本次运行已经完成了 {steps}，下一步是 {next}——请使用 --resume`,"preserve.gate.powerCycle":`上一次备份尝试失败了，在再次运行此步骤之前，必须先给相机断电重启——在同一次启动中重试，可能会读到过时或空白的字节（实测：一次重试的备份读到的是引导程序的启动字，而不是启动配置记录）。请给相机断电重启（拔下再重新插上，或使用它的电源开关），然后再次运行备份，并在询问时确认已断电重启：本次运行无法自己察觉这一点。记录的失败：{error}`,"preserve.gate.noErrorText":`（无错误文本）`,"preserve.gate.patchAfterBackup":`{step}在备份之后运行：本次运行会先导出原厂方案能读取的每个区域并保存下来，然后才做其他任何事——那份备份是这台相机唯一的副本。请先运行备份步骤。`,"preserve.gate.commitAfterBackup":`{step}在备份之后运行（参见补丁步骤）`,"preserve.gate.commitAfterPatch":`{step}在补丁步骤之后运行，补丁步骤会记录它要暂存的内容`,"preserve.gate.commitNeedsPatch":`{step}需要{banks} 的补丁，而补丁步骤没有记录任何补丁——请重新运行补丁步骤`,"preserve.gate.commitFiles":`{step}需要运行目录中的备份文件，但它们缺失了：{files}——没有它们，提交就没有还原来源，因此拒绝执行`,"preserve.gate.drainNoCommit":`{step}要通过扩大的窗口读取打过补丁的芯片，而本次运行没有已完成的提交——在原厂相机上全闪存读取会停滞。请先运行提交（或从提交继续）；如果提交已经完成但没有留下检查点，请明确跳过（allowJump）。`,"preserve.gate.drainRefused":`全闪存读取步骤在 {build} 上拒绝运行：{note}`,"preserve.gate.detectedBuild":`检测到的版本`,"preserve.gate.drainHazard":`全闪存读取步骤在 {build} 上拒绝运行：在这个版本未打补丁的固件上开始全闪存读取会让相机崩溃（它从一个不是闪存地址的值读取；在模拟器上测得：提供 32 KB 后相机出错）。使读取安全的修改位于 {sites}，但它不在本次运行为{bank} 记录的修改之中——请在全闪存读取之前运行补丁步骤（并完成写入）。`,"preserve.gate.drainFiles":`{step}需要 {files}（读出的镜像要用每个已写入槽位的采集数据做后处理），但运行目录中没有它`,"preserve.gate.restoreNoCommit":`{step}会把原始槽位写回到补丁之上，而本次运行没有已完成的提交——没有任何可以还原的内容。请先运行提交（或从提交继续），或者明确跳过（allowJump）以还原一台已经打过补丁的相机。`,"preserve.gate.restoreNeedsPatch":`{step}需要每个已写入槽位的补丁摘要（用于暂存长度）——请先运行补丁步骤`,"preserve.gate.restoreNoForm":`还原步骤在 {build} 上拒绝运行：原始固件没有任何一种形式既能通过相机自身的检查、又能存回为原始字节——原始固件的校验和是 0xB7AB9D17（实测），而不是相机要求的 0xFFFF。本次运行将以手中的完整镜像结束，补丁仍保留在相机中；原始内容只能用全闪存编程器写回。`,"preserve.gate.restoreFiles":`{step}需要 {files}（每个已写入槽位的原始内容，来自备份步骤），但运行目录中没有它`,"preserve.gate.verifyNoRestore":`{step}会把重新启动后的读取与备份比较，而本次运行没有已完成的还原——打过补丁的槽位会显示为差异。请先运行还原（或从还原继续）；如果还原已经完成但没有留下检查点，请明确跳过（allowJump）。`,"preserve.gate.verifyNeedsBackup":`{step}需要 {file}（比较的参照），但运行目录中没有它`,"preserve.gate.needsBanks":`{step} 需要备份步骤读取的槽位，但当前状态中没有`,"preserve.gate.noBanks":`本次运行没有选择任何槽位：{what}`,"preserve.gate.bankRefused":`{bank} 无法写入：{why}`,"preserve.gate.recoveryOnly":`此版本的补丁只能从恢复槽位 R 启动：{note}——本次运行会写入{bank}，而引导程序永远不会从那里运行它`,"slots.image.tooSmall":`文件太小，无法容纳镜像头部`,"slots.image.notWordSized":`镜像大小必须是 4 的倍数（实际为 {size} B）`,"slots.image.tooLong":`镜像为 {size} B；引导程序会拒绝任何 header.length >= {limit} 的镜像，所以它永远无法启动`,"slots.image.noHeader":`{at} 处没有镜像头部（魔数 {magic}，预期为 {expected}）——这必须是解密后的 Seek 固件镜像，而不是加密的槽位或闪存镜像`,"slots.image.stackOutside":`初始栈指针 {address} 不在 LPC43xx 的 SRAM 中——这看起来不像是解密后的镜像`,"slots.image.stackUnaligned":`初始栈指针 {address} 没有按字对齐`,"slots.image.notThumb":`复位向量 {address} 不是 Thumb 地址`,"slots.image.noKeyPair":`这个文件的名称中不含它的密钥对，而这台相机的密钥对和已解码的应用程序密钥对在镜像中都没有恰好出现一次，因此无法判断这个镜像是为哪些密钥构建的。解密出的文件，其名称中会带有它所包含的密钥。`,"slots.image.keyMismatch":`文件名声称密钥 A 为 {keyA}、密钥 B 为 {keyB}，但 {mismatch}。两个密钥都必须存在，且各恰好出现一次。`,"slots.image.keyInHeader":`这个镜像在 {at} 处保存了一个密钥，位于明文头部窗口之内——拒绝修补它`,"slots.image.keysOverlap":`文件名中的密钥 A 和密钥 B 对应到 {at} 和 {other} 处重叠的字节——它们必须是两个不同的 16 字节值`,"slots.image.retargetLost":`重定向之后，镜像中这台相机的密钥对没有恰好出现一次——拒绝构建一个其后续升级无法由引导程序找到密钥的载荷`,"slots.image.noStageKey":`镜像中没有 2016 固件线的密钥对，因此没有可用于编码它的暂存密钥`,"slots.image.ffSumNoKeys":`这个镜像的字累加和是 16 Hz FF 的 0xFFFF，但它没有 1.3.0.8-FF 密钥对（两半各出现一次），因此无法构建它的暂存形式。没有写入任何内容。`,"slots.image.ffNotPlain":`这是 1.3.0.8 FF（16 Hz）镜像，它以自己的密钥 A 形式暂存（ff-form.ts），而不是作为明文镜像。没有写入任何内容。`,"slots.plan.otherFirmware":`计划是为固件 {firmware} 生成的，但分析读到的是 {version}。计划已过时；请重新生成。没有写入任何内容。`,"slots.plan.otherFirmwareUnknown":`计划是为版本未知的固件生成的，但分析读到的是 {version}。计划已过时；请重新生成。没有写入任何内容。`,"slots.plan.otherCamera":`计划所针对的相机序列号：{planSerial}；分析读到的序列号：{serial}。拒绝在这里写入。没有写入任何内容。`,"slots.plan.cameraUnknownSerial":`未知`,"slots.plan.unknownSerial":`未知`,"slots.plan.otherAddress":`计划的目标地址是 {address}，但此版本的{name} 位于 {at}`,"slots.plan.notRead":`分析不再读取{name}。没有写入任何内容。`,"slots.plan.edited":`计划的校验和与其载荷不符，说明计划被修改过。没有写入任何内容。`,"slots.plan.outsideBank":`载荷为 {size} B，超出了{name} 的范围`,"slots.plan.riskAck":`{risk}。写入它需要 acknowledgeRisk: true。没有发送任何内容。`,"slots.plan.plainStaging":`这台相机无法从这里接受以明文暂存的镜像：{reason}。没有写入任何内容。`,"slots.plan.noKeyTable":`分析没有指明这台相机引导程序的密钥表，因此无法把镜像重定向到它`,"slots.commit.unread":`CompleteMemoryUpgrade 之后无法读取提交状态，因此{name} 可能只写入了一部分。在做任何其他操作之前，请重新读取槽位，并保留好你导出的镜像。`,"slots.commit.refused":`相机在提交时以 {status} 拒绝了对{name} 的写入：{cause}。没有写入任何内容；该槽位没有改变。在做任何其他操作之前，请重新读取槽位。`,"slots.commit.eraseStage":`CompleteMemoryUpgrade 对{name} 返回了 {status}（{cause}）：没有写入任何新内容，但擦除可能已经开始，因此该槽位可能已被部分擦除。在做任何其他操作之前，请重新读取槽位，并保留好你导出的镜像。`,"slots.commit.partial":`CompleteMemoryUpgrade 返回了 {status}（{cause}）——{name} 可能只写入了一部分。在做任何其他操作之前，请重新读取槽位，并保留好你导出的镜像。`,"slots.commit.stagingStatus":`相机在偏移 {offset} 处暂存{name} 时报告了 {status}——已在 CompleteMemoryUpgrade 之前中止，因此没有向闪存写入任何内容`,"commit.cause.badChecksum":`传输校验和与暂存的字节不符`,"commit.cause.unsupported":`镜像无法用相机的密钥解密，或者数据类型被拒绝`,"commit.cause.acceptance":`镜像在擦除任何内容之前就被其校验拒绝（校验方式取决于版本）`,"commit.cause.notArmed":`没有打开任何槽位升级`,"commit.cause.eraseFailed":`擦除阶段失败`,"commit.cause.programFailed":`写入阶段失败`,"commit.cause.verifyFailed":`校验阶段失败`,"commit.cause.unknown":`一个此处未知的状态`,"copy.refused.ontoItself":`{name} 不会复制到它自己。没有写入任何内容。`,"copy.refused.source":`{why}。没有写入任何内容。`,"copy.refused.noPlain":`{name} 没有可复制的解密镜像。没有写入任何内容。`,"restore.refused.zipUnreadable":`{file} 是一个在这里无法读取的 ZIP（{error}）。没有写入任何内容。`,"restore.refused.noWholeFlash":`{file} 中没有完整闪存。可接受的 ZIP 是：含有 {preserve} 的 Preserve 运行文件（在其完整导出步骤运行之后）、“导出并解密 4.x/Nano”的 zip（{dump}）或“导出全部选择器”的 zip（{selectors}）；这个 ZIP 中的内容：{names}。没有写入任何内容。`,"restore.refused.noWholeFlashPatched":`{file} 中没有完整闪存。可接受的 ZIP 是：含有 {preserve} 的 Preserve 运行文件（在其完整导出步骤运行之后）、“导出并解密 4.x/Nano”的 zip（{dump}）或“导出全部选择器”的 zip（{selectors}）；这个 ZIP 中的内容：{names}。其中的 {patched} 是带有本次运行临时补丁的闪存，因此不予接受。没有写入任何内容。`,"restore.refused.zipEmpty":`无`,"restore.refused.wrongSize":`完整闪存备份为 {full} B（4 MB，即 J-Link 读取的整片芯片）；{file} 为 {size} B。没有写入任何内容。`,"restore.refused.noBank":`此版本的计划中没有{bank}。没有写入任何内容。`,"restore.refused.outsideFlash":`{name} 不在 4 MB 闪存范围之内。没有写入任何内容。`,"restore.refused.gap":`{where}没有被 {file} 所来自的那次导出读取：根据其 manifest.json，{address} 是一个空缺。没有可还原的镜像。没有写入任何内容。`,"restore.refused.gapReason":`{where}没有被 {file} 所来自的那次导出读取：根据其 manifest.json，{address} 是一个空缺（{gap}）。没有可还原的镜像。没有写入任何内容。`,"restore.refused.gapFill":`{where}没有被 {file} 所来自的那次导出读取：根据其 manifest.json，{address} 是一个空缺，以 {fill} 填充。没有可还原的镜像。没有写入任何内容。`,"restore.refused.gapReasonFill":`{where}没有被 {file} 所来自的那次导出读取：根据其 manifest.json，{address} 是一个空缺（{gap}），以 {fill} 填充。没有可还原的镜像。没有写入任何内容。`,"restore.refused.empty":`{where}是空的：每个字节都是 0xFF。写入会写入一个镜像，无法让槽位保持擦除状态，因此空槽位无法通过写入来还原。没有写入任何内容。`,"restore.refused.fill":`{where}的每个字节都是 {fill}，这是导出在没有读到内容的地方写入的填充值：这次导出没有读取这个槽位。没有可还原的镜像。没有写入任何内容。`,"restore.refused.notDecrypted":`无法从这个文件还原{where}：{why}。没有写入任何内容。`,"support.noWriteArm":`此版本没有该槽位的写入打开方式`,"support.noStagingEmpty":`此版本没有暂存形式，因此不会写入空槽位`,"support.buildUnknown":`版本未知`,"support.unverifiedStaging":`此版本属于加锁的 0.x/1.x 固件线，但不是测量过完整备份补丁表的版本之一（0.8.0.0 .. 1.3.0.8 以及 1.0.3.0 / 1.0.3.2），因此它的槽位采用的暂存形式未知，不会写入任何内容`,"support.unknownFamily":`相机的固件系列未知，因此它的槽位写入时使用的密钥也未知；而相机会接受用错误密钥写入的槽位，之后却无法从中启动。请导出并解密这台相机，根据导出的镜像识别它，然后用 --family 指定它的固件系列。`,"support.noReadCommand":`早于 0.8.0.0 的固件没有 GetFeaturedFirmwareData（导出读取闪存所用的命令）的读取处理程序。在 0.7.0.7 和 0.7.0.8 上，它位于 RPC 方法表的 0x4F 处，但只注册为 setter（写入处理程序），因此导出发送的 control-IN 读取无法被分派（0.x/1.x 标签页的完整备份流程改为通过线路 ID 0x58，即 GetFeaturedData，读取这两个版本）；在 0.7.0.7 之前，线路 ID 0x4F 是 UploadFirmwareRowSize；在 0.3.0.1 上，线路 ID 0x52——导出用来打开窗口的那个——是 EnterBootloaderMode，而不是 BeginFirmwareUpgrade：相机仍停留在它的应用程序中，但每次打开都会设置一个闪存目标并开启该版本的固件升级阶段（之后 GetErrorCode 读到 0x00400000），这并不是读取窗口。这些信息是从镜像自身的方法表（两个处理程序列）中恢复出来的；参见 test/firmware/facts.json。`,"support.noWritePath":`这些版本通过本工具箱不会发送的一种较旧的升级流程接收新固件，而且它们的槽位从未被映射过，因此不会写入任何内容。`,"support.versionUnread":`无法读取固件版本，因此版本、它的槽位及其暂存形式都未知；不会对它进行任何读取或写入`,"support.versionNotDotted":`固件版本“{version}”不是点分格式的版本号，因此版本、它的槽位及其暂存形式都未知；不会对它进行任何读取或写入`,"support.olderThanFirst":`固件 {version} 早于 {first}：它的 RPC 表中没有 GetFeaturedFirmwareData（槽位读取发送的命令）的读取处理程序，因此既不会向它发送读取，也不会发送写入（证据见 early-compact）`,"support.modernOnLocked":`固件系列 modern-4x 适用于 2.x、4.x、10.x、42.x 和 44.x；{version} 属于 0.x / 1.x 加锁固件线，需要 legacy-auth 或 compact-2016`,"support.lockedOnModern":`固件系列 legacy-auth 适用于 0.x / 1.x 加锁固件线；{version} 属于现代固件线，需要 modern-4x`,"support.notCompactPro":`固件系列 compact-2016 适用于 Compact PRO 1.0.3.x 固件线；{version} 不在其中`,"support.earlyCompact":`固件系列 early-compact 只适用于早于 {first} 的版本，而 {version} 按 legacy-auth 读取`,"support.generic":`相机的固件系列尚未识别（family generic），因此槽位布局和暂存形式都未知；请在读取或写入槽位之前先识别相机`,"support.noPlan":`固件系列 {family} 没有槽位计划：它的槽位布局和暂存形式都未知`,"support.noArmPlain":`此版本的表在普通通道上不会打开 {address} 处的模式 {mode}`,"support.noArmToken":`此版本的表在令牌通道上不会打开 {address} 处的模式 {mode}`,"support.windowElsewhere":`{bank} 在完整备份流程中的槽位窗口位于 {at}，而不是 {address}`,"support.noDumpWindow":`此版本的 BeginFirmwareUpgrade 表中没有{bank} 在 {address} 处的窗口`,"support.capabilityRefused":`{family} 不支持{capability}：{reason}`,"support.capability.dump":`导出`,"support.capability.allSelectors":`“导出全部选择器”`,"support.capability.decrypt":`解密`,"support.capability.deviceInfo":`“信息”标签页的完整读取`,"support.capability.flash":`槽位写入`,"slots.unread.noWindow":`{name}（{address}）在此版本上无法读取：它的选择器表在那里没有窗口，因此没有为它打开任何读取`,"slots.unread.missing":`相机分析中缺少{name}`,"slots.unread.notRead":`{name} 没有被读取`,"slots.refused.nothingWritten":`{refusal}。没有写入任何内容。`,"slots.refused.versionUnknown":`分析没有说明相机运行的是哪个固件，而槽位命令在不同版本上的含义不同。请重新读取设备信息。`,"slots.refused.versionUnknownWrite":`分析没有说明相机运行的是哪个固件。没有写入任何内容。`,"slots.refused.emptyInput":`输入为空`,"slots.refused.emptyNotWritable":`{name} 是空的，在此版本上无法写入：{reason}`,"slots.refused.noRaw":`在此版本上，{name} 不能接受原始字节：{reason}`,"slots.refused.noPlain":`在此版本上，{name} 不能接受解密后的镜像：{reason}`,"slots.refused.noStaging":`{name} 在此版本上没有暂存形式，因此无法为它编码镜像`,"slots.refused.rawTooLong":`{size} B 超过了{name} 的大小（{bankSize} B）`,"slots.refused.imageTooLong":`镜像为 {size} B，超过了{name} 的大小（{bankSize} B）`,"preserve.routeNote.recoveryOnly":`2014 年的引导程序不接受此版本在槽位 A 或 B 中的校验和，而会不经检查直接启动恢复槽位 R（0x14070000），因此补丁会写入恢复槽位 R，且只写入那里`,"preserve.refused.recoveryOnly":`此版本只从恢复槽位 R 运行：{note}`,"decryptFile.wrongSize":`固件槽位为 {size} B（{kib} KB）；这个文件为 {count} B`,"decryptFile.erasedBank":`空，没有可解密的内容：全部 {size} B 读出都是 0xFF（已擦除的槽位）`,"decryptFile.erasedHeader":`已擦除：头部窗口全是 0xFF，因此该槽位中没有镜像；不会解密任何内容`,"decryptFile.noHeader":`没有镜像头部（魔数 {magic}），因此没有可解密的镜像`,"decryptFile.lengthOutOfRange":`header.length {length} 超出范围；没有可解密的镜像`,"decryptFile.ffKeyB":`已用 FF 1.3.0.8 密钥 B 解密 {size} B：镜像存储为镜像与其密钥块 1 密钥流的异或，头部窗口保持原样`,"decryptFile.notRecovered":`密钥未能恢复：镜像解密后的复位向量不是 Cortex-M 入口（密钥{check}）；不会解密任何内容`,"decryptFile.storedPlain":`以明文存储：槽位中存放的是运行时原样的镜像（2014 年的明文链，恒等密钥流），因此没有密钥，解密后的镜像就是镜像本身`,"decryptFile.decrypted":`已用从这个槽位恢复的密钥解密 {size} B（{check}）`,"decryptFile.decryptedNamed":`已用从这个槽位恢复的密钥解密 {size} B（{check}；它是{key}）`,"read.reason.shortRead":`读取不完整（{size} B）`,"read.reason.noParse":`无法解析镜像头部`,"read.reason.noHeader":`没有镜像头部（魔数 {magic}）`,"read.reason.lengthOutOfRange":`header.length {length} 超出范围`,"read.reason.stopped":`槽位读取在 {count}/{size} B 处停止`,"read.reason.notInPlan":`在固件 {version} 上无法读取：它的计划（{table}）在 {address} 处没有窗口，因此没有为它打开任何读取`,"read.reason.notInPlanUnknown":`在版本未知的固件上无法读取：它的计划（{table}）在 {address} 处没有窗口，因此没有为它打开任何读取`,"read.reason.staleDescriptor":`该窗口提供的是过时的读取描述符的字节——字 0 为 {word}、复位向量为 {hex}，这是 0x14000000 的向量表，而不是这个槽位的内容，因此没有对它做任何分析：{remedy}`,"read.reason.spentReader":`无法读取相机的槽位——{remedy}`,"read.spentRemedy":`本次启动的窗口读取额度可能已经用尽；请给相机断电重启，然后重试`,"checkKey.unnamed.wordNotRead":`无法读取相机的活动槽位字（fw info roots，选择器 10）`,"checkKey.unnamed.wordNamesNoBank":`相机的活动槽位字为 {word}，它不对应任何槽位`,"checkKey.unnamed.cfg0NotRead":`没有读取启动配置字，因此不知道引导程序在进入{bank} 之前是否检查过它`,"checkKey.unnamed.noZeroSum":`相机报告它进入了{bank}，但在本次读取中，{bank} 解密后的字累加和不为零`,"checkKey.unnamed.noZeroSumUnchecked":`相机报告它进入了{bank}，而启动配置字 {word} 把它排在最后，所以引导程序进入它时没有检查；但在本次读取中，{bank} 解密后的字累加和不为零`,"report.detected":`{family}（读取后得分 {score}，依据下方的证据）`,"report.detectedAmbiguous":`{family}（读取后得分 {score}，依据下方的证据；不确定）`,"report.cell.yes":`是`,"report.cell.no":`否`,"report.cell.notApplicable":`不适用`,"report.cell.unknown":`未知`,"report.cell.recoveryOnly":`仅恢复`,"report.keyRow.whitening":`白化常数 K`,"report.keyRow.store":`存储密钥`,"report.keyRow.check":`检查密钥`,"report.keyRow.table":`密钥表`,"report.keyRow.keys":`密钥`,"report.keyRow.a":`密钥 A`,"report.keyRow.b":`密钥 B`,"report.keyRow.tableAt":`密钥表位置`,"report.key.notIdentified":`（未识别）`,"report.key.candidates":{other:`{count} 个候选，均未确认`},"report.key.tableAt":`引导程序块中的 {offset}，已与某个槽位核对确认`,"report.key.plainChain":`不需要：槽位以明文固件存储，因此槽位按原样读取和写入`,"report.key.tableRefused2016":`未读取——在这条固件线上，引导程序块（0x14000000）在所有通道上都被拒绝读取`,"report.checkKey.named":`{key} {hex}{pair}`,"report.checkKey.namedFrom":`{key} {hex}{pair}，根据{bank} 指明——相机报告它在引导程序检查之后进入了该槽位`,"report.checkKey.inferredFrom":`{key} {hex}{pair}，从{bank} 推断得出——相机报告它进入了该槽位：引导程序进入该槽位时不检查，并以它检查其他槽位所用的密钥运行它`,"report.checkKey.pair":`（{pair}的密钥块 1）`,"keyPair.cp103":`Compact PRO 1.0.3.x 9 Hz 密钥对`,"keyPair.cp1032ff":`Compact PRO 1.0.3.x FF 密钥对`,"report.checkKey.notNamed":`未指明——{why}`,"report.checkKey.couldNotName":`本次读取无法指明它`,"report.storeKey.checkKeyUnnamed":`其引导程序检查槽位时使用的密钥（本次读取未指明）：应用程序写入的每个槽位都以该密钥存储`,"report.storeKey.checkKey":`{key}：应用程序写入的每个槽位都以其引导程序检查时使用的密钥存储`,"report.storeKey.unknown":`未知——没有读取存放设备专属密钥槽的引导程序块`,"report.storeKey.keyBUnidentified":`密钥 B（没有烧录设备专属密钥；密钥 B 本身未识别）`,"report.storeKey.keyB":`密钥 B（没有烧录设备专属密钥）`,"report.staged.plain":`以明文暂存（镜像原样，不使用密钥）`,"report.staged.slotKeystream":`以其镜像自身的密钥块 0 暂存`,"report.staged.keyA":`以由当前启动槽位和正在运行的应用程序推导出的密钥暂存`,"report.staged.ffVendor":`按厂商应用暂存 16 Hz FF 镜像的方式暂存（镜像 XOR 其自身的密钥块 0），由相机以密钥 B 存储`,"progress.backupBlock":`备份：块 {address}`,"progress.backupDone":`备份：已读取每个块`,"progress.checkBlock":`检查：块 {address}`,"progress.checkDone":`检查：已读取每个块`,"progress.writingBank":`正在写入{bank}`,"progress.restoringBank":`正在还原{bank}`,"progress.staged":`{label}：已暂存 {done}/{total} B`,"progress.wholeFlash":`全闪存读取：{got}/{total} B`,"progress.readWindow":`读取 {address} subcmd={subcmd} …`,"progress.readWindowAuth":`读取 {address} subcmd={subcmd}（需解锁令牌）…`,"progress.windowsRead":`完成——已读取 {ok}/{total} 个窗口。`,"progress.readingBank":`正在读取{bank}…`,"progress.analysing":`正在分析…`,"progress.probeSelector":`探测选择器 {selector} …`,"progress.selectorsArmed":`完成——已激活 {armed}/{span} 个选择器，其中 {withData} 个有数据。`,"progress.recoveringKey":`解密：正在为 {address} 恢复密钥…`,"slots.window.unread":`{bank} {address}（subcmd {subcmd}）无法读取：{error}`,"slots.read.refusedBuild":`拒绝读取固件槽位：{reason}。除了版本读取外没有发送任何命令，因此没有触及任何槽位。`,"slots.backup.notSaved":`备份 {file} 没有保存，因此没有写入任何内容。没有先保存备份，写入就绝不会运行；请在可以保存备份时重试。`,"slots.backup.notSavedWhy":`备份 {file} 没有保存（{error}），因此没有写入任何内容。没有先保存备份，写入就绝不会运行；请在可以保存备份时重试。`,"usb.speed.high":`高速（480 Mbit/s）`,"usb.speed.full":`全速（12 Mbit/s）`,"usb.speed.code":`代码 {code}`},shared:{"runPanel.percent":`{value}%`,"runPanel.progressLabel":`{label}进度`,"runPanel.logLabel":`{label}日志`,"runPanel.trimmed":{other:`… 已省略前面的 {count} 行`},"runPanel.lineCount":{other:`{count} 行`},"status.idle":`空闲。`,"status.cancelled":`已取消。`,"status.cancelling":`正在取消…`,"status.failedSeeLog":`失败——请查看上方的日志。`,"cameraLock.inUseElsewhere":`相机正在另一个标签页或窗口中使用——请先在那里完成操作或将其关闭。`,"backup.downloadNote":`zip 文件会在发送任何内容之前自动下载。浏览器不会告诉你下载何时真正写入磁盘，所以在依赖它之前，请先到下载文件夹中确认它已存在。`,"device.none":`未选择设备。`,"device.disconnected":`设备已断开。`,"device.revoked":`权限已被撤销。`,"device.unknownProduct":`未知产品`,"device.unknownVendor":`未知厂商`,"hint.udev":`在 Linux 上，相机需要一条 udev 规则，浏览器才能打开它：

{rule}

然后拔下相机再重新插上。Snap 和 Flatpak 版的 Chromium 常被沙盒隔离，无法访问原始 USB 设备；.deb 或 .rpm 版才可靠。`,"hint.windows":`Windows 需要先为相机绑定 WinUSB 驱动，浏览器才能访问它。使用 Zadig（https://zadig.akeo.ie/）：Options → List All Devices，选择以你的相机命名的条目——例如“CompactPRO FF”——选择 WinUSB，然后点击 Replace Driver。`,"hint.holding":`另一个程序或系统驱动正在占用相机——同一时间只能有一个进程占用 USB 接口。请退出其他与它通信的程序，然后拔下相机再重新插上。`,"hint.recipientFallback":`或者在读取选项中把 recipient 设为“device”，这样不需要占用接口。`,"hint.optionsInvalid":`打开“选项”，查看各字段下方关于取值范围的说明。`,"hint.usbTimeout":`相机接受了请求，但一直没有应答。请拔下相机再重新插上，然后改用更小的 chunk 再试（64 是在所有设备上都可用的值）。`,"hint.usbStalled":`相机拒绝了该请求。这通常表示它的固件不支持该请求。本页在读取任何内容之前都会先询问相机属于哪个固件系列，所以一再被拒绝的请求，正是按相机自己报告的系列发出的。请在“信息”标签页上查看固件版本。`,"hint.usbNotOpen":`另一个程序或系统驱动正在占用相机。请关闭它，或者在读取选项中把 recipient 设为“device”，这样不需要占用接口。`,"hint.usbTransferFailed":`拔下相机再重新插上，然后重试。`,"hint.deviceMode":`相机无法退出成像模式。请拔下相机，等它完全断电，再重新插上。`,"hint.deviceWindow":`该固件系列使用的选择器映射与相机不符。请在 4.x/Nano 标签页上打开“选项”，运行“导出全部选择器”，查看相机实际开放了哪些内容。`,"hint.deviceVersionUnknown":`没有发送任何可能改变相机的命令。请拔下相机，再重新插上，等它完成启动后重试；能报告固件版本的相机会被正常读取。`,"hint.imageMalformed":`该文件不是解密后的 Seek 固件镜像。`,"hint.imageUnsupported":`这个镜像无法按原样打包给相机。`,"hint.imageKeyTable":`该镜像中没有其文件名所声称的密钥对。请原样使用导出时写出的解密文件，包括文件名。`,"hint.flashRefused":`没有向相机写入任何内容。`,"hint.familyUnsupported":`没有读取或写入任何内容。每个标签页适用于一段固件版本：0.x 和 1.x 相机请使用“导出并解密 0.x/1.x 2014/2016”，4.x 和 Nano 相机请使用“导出并解密 4.x/Nano”。“信息”标签页会告诉你相机该用哪个标签页。`,"hint.firmwareTooOld":`在这里，没有任何固件系列能读取这个版本：它的固件不处理此标签页读取闪存所用的命令，因此没有向它发送任何可能被误读的命令。运行 0.7.0.7 或 0.7.0.8 的 Compact 可以在“导出并解密 0.x/1.x 2014/2016”中读取。用 SPI 编程器或通过 SWD/J-Link 读出的闪存镜像，仍可在本页的“解密文件/槽位”中解密。`,"hint.powerCycle":`在本向导中：拔下相机再重新插上，按“连接设备”并选择它，然后重新开始同一步骤。本次运行仍保留在页面中——无需从运行文件继续。`,"deviceInfo.running":`正在运行的固件`,"deviceInfo.version":`版本`,"deviceInfo.family":`固件系列`,"deviceInfo.build":`构建`,"deviceInfo.bootloader":`引导程序`,"deviceInfo.platform":`平台`,"deviceInfo.serial":`序列号`,"deviceInfo.usbLink":`USB 连接`,"deviceInfo.bootConfig":`启动配置`,"deviceInfo.bootedFrom":`本次启动自`,"deviceInfo.nextStart":`下次启动`,"deviceInfo.upgradeTarget":`升级目标（相机自身的升级）`,"deviceInfo.bankAt":`{bank}，地址 {address}`,"deviceInfo.perDeviceKey":`设备专属密钥`,"deviceInfo.notProgrammed":`未烧录——相机会退而使用密钥 B`,"deviceInfo.keysTitle":`从这台相机读取的密钥`,"deviceInfo.foundAt":`所在位置`,"deviceInfo.flashOffset":`闪存偏移 {offset}`,"deviceInfo.keyA":`密钥 A`,"deviceInfo.keyB":`密钥 B`,"deviceInfo.keysConfirmed":`已通过与某个槽位的密钥流状态相匹配得到确认，该状态是从密文本身恢复出来的。上传的数据经过构造，使每个槽位都以引导程序的存储密钥（{storeKey}）保存它；如果应用程序的存储密钥不是这一个，则以当前启动槽位自己的密钥保存。`,"deviceInfo.keysDecrypted":`每个槽位都已在浏览器中解密：利用它自身已知为零的复位向量求出密钥流。能解密不等于能启动：引导程序只会尝试 {storeKey} 和密钥 A，因此用其他任何密钥写入的槽位，即使校验和完全正确，也仍会被跳过。没有写入任何内容。`,"deviceInfo.orphan":{other:`**{banks} 中存有有效的固件镜像，但它是用这台相机的引导程序不认识的密钥加密的。**镜像完好，校验和也正确，但引导程序检查槽位时只尝试 {storeKey} 和密钥 A，所以会将其跳过，转而启动其他内容。`},"deviceInfo.orphanIsTarget":`这正是升级时写入的槽位。这台相机上运行的应用程序会用那个未知密钥重新加密，所以**通过本页写入只会再产生一个引导程序无法启动的槽位**——相机会继续运行{bank}。用 SPI 编程器或通过 SWD/J-Link 直接写入该槽位，可以绕过这个问题。`,"deviceInfo.otherBank":`另一个槽位`},info:{"status.notRead":`尚未读取。`,"status.reading":`正在读取…`,"status.noVersion":`相机未报告版本。`,"status.tooOld":`已读取。固件 {version} 早于 0.8.0.0——没有读取其他内容。`,"status.read":`已读取。固件 {version}。`,"read.title":`读取相机`,"read.description":`只读。询问相机运行什么固件、如何启动、持有哪些密钥、每个槽位存放了什么：与 seek-fw info 的读取相同。不会写入任何内容。`,"read.actions":`信息操作`,"read.button":`读取固件版本`,"read.connectFirst":`请先在上方连接相机，然后按“读取固件版本”。`,"read.showDetails":`在日志中显示详细信息`,"read.panel":`固件版本`,"result.title":`相机报告的内容`,"result.version":`固件版本`,"result.build":`构建`,"result.range":`版本范围`,"result.tab":`适用于这台相机的标签页`,"result.rangeLegacy":`0.x / 1.x：2014 年和 2016 年的相机`,"result.rangeModern":`2.x 及更新：4.x、Nano 和 Mosaic 相机`,"result.rangeUnknown":`未知`,"result.noVersion":`**相机没有报告固件版本。**没有发送其他任何内容。请拔下相机，再重新插上，等它完成启动后重新读取。`,"result.noTab":`没有标签页能读取这个版本。`,"result.openTab":`请为这台相机打开<tab>{tab}</tab>标签页。该标签页在读取任何内容之前会再次询问相机属于哪个固件系列，并拒绝不属于其适用系列的相机。`,"tabs.title":`各标签页的用途`,"tabs.intro":`共有五个标签页，按以下顺序排列。每个都是独立的页面，页头会显示你当前所在的标签页。`,"tabs.caption":`各标签页的功能、适用的相机以及是否写入`,"tabs.tab":`标签页`,"tabs.does":`功能`,"tabs.cameras":`相机`,"tabs.writes":`是否写入相机？`,"tabs.info.does":`读取相机报告的内容：它的固件、它的应答所对应的固件系列、启动方式、密钥以及每个槽位。与 seek-fw info 的读取相同。不写入任何内容。`,"tabs.info.cameras":`任何 WebUSB 能打开的 Seek 相机。`,"tabs.info.writes":`否。`,"tabs.preserve.does":`为相机的 4 MB 闪存制作完整副本，每一步之后都保存一个运行文件。为了读取全部闪存，它会暂时给固件打补丁，然后把原始固件放回去并加以检查。它会一步一步地引导你完成。`,"tabs.preserve.cameras":`运行 0.x 和 1.x 固件的相机：2014 年的 Compact 版本、2016 年的 Compact PRO 版本（1.0.3.x），以及 1.3.0.8 FF（16 Hz）Compact 版本。`,"tabs.preserve.writes":`是，分两步，每一步都会先征求确认。它会让相机恢复原样。`,"tabs.v4.does":`读取 4.x 或 Nano 相机的整片闪存，并解密找到的固件槽位。只读：它只发送六个读取命令，不发送任何写入命令。`,"tabs.v4.cameras":`运行 4.x 固件的相机（Compact、Compact PRO、Compact XR）、Mosaic（10.x 和 2.x）以及 Nano（42.x 和 44.x），2018 年起。`,"tabs.v4.writes":`否。`,"tabs.decrypt.does":`解密你已有的文件：完整的闪存镜像（逐个槽位解密），或单独一个 64 KB 固件槽位。结果可以下载。`,"tabs.decrypt.cameras":`无。它不使用相机，因此不连接任何设备也能使用，在任何浏览器中都能使用。`,"tabs.decrypt.writes":`否。它只写出下载的文件。`,"tabs.slots.does":`读取三个固件槽位（槽位 A、槽位 B 和恢复槽位 R），显示每个槽位存放的内容以及相机从哪个槽位启动，并可以一次导出或写入一个槽位。`,"tabs.slots.cameras":`运行 0.8.0.0 及更新固件的相机。`,"tabs.slots.writes":`是，一次一个槽位，每次写入前都会先征求确认。`,"split.title":`2016 和 1.3.0.8 FF 版本在哪里`,"split.where":`2016 年的 Compact PRO 版本（1.0.3.0 和 1.0.3.2，包括它们的 FF 变体）以及 1.3.0.8 FF（16 Hz）Compact 版本**不是** 4.x 相机，也不能按 4.x 相机的方式读取。它们使用的是 2014–2017 年那套加锁的协议；其固件存储槽位的方式，要么是另一种加密（2016），要么是 2014 年的明文链加上只能从恢复槽位启动的路径（FF）。因此它们归**导出并解密 0.x/1.x 2014/2016** 处理，4.x/Nano 标签页会在读取任何内容之前拒绝它们。`,"split.evidence":`它们在 0.x/1.x 标签页上可用的证据：Preserve 流程为它们各自推导出了补丁，两者在模拟器中的运行都全部通过。1.0.3.0 版本在其原生的 2016 镜像上走完了备份、补丁、提交、全闪存读取、还原和验证；1.3.0.8 FF 走完了它的恢复槽位路径。在测试台的相机（一台 Compact PRO 1.0.3.0）上，Preserve 步骤 02 的读取已完成，期间没有重置、没有写入，相机被识别为 2016 加密。在这些版本上，4.x 选择器映射的 63 个选择器中有 38 个被拒绝，所以 4.x 标签页对它们只能返回空缺。`,"split.stay":`所以它们留在 0.x/1.x 标签页；4.x/Nano 标签页也没有能把它们转过去读取的固件系列选择器。`,"report.camera":`相机`,"report.product":`产品`,"report.manufacturer":`制造商`,"report.serial":`序列号`,"report.platform":`平台`,"report.usbLink":`USB 连接`,"report.noProduct":`（无产品字符串）`,"report.none":`（无）`,"report.unreadable":`（无法读取）`,"report.firmware":`固件`,"report.running":`正在运行`,"report.bootloader":`引导程序`,"report.family":`固件系列`,"report.readUnder":`读取所用系列`,"report.detected":`检测结果`,"report.boot":`启动`,"report.booted":`本次启动`,"report.lastStart":`上次启动`,"report.running1308":`正在运行（1.3.0.8）`,"report.nextStart":`下次启动`,"report.upgradeTarget":`升级目标`,"report.notReplayed":`（未询问）`,"report.targetConfirmed":`{slot}（已在通信中确认）`,"report.buildNotKnown":`未知：{why}。16 Hz FF 镜像需要相机说明它运行的是哪个版本（“固件槽位操作”标签页会询问）`,"report.buildWhy":`{build}：{why}`,"report.buildFf":`16 Hz FF 1.3.0.8 版本`,"report.build8Hz":`8 Hz 1.3.0.8 版本`,"report.keys":`密钥`,"report.slots":`槽位`,"report.slotsCaption":`读取时所见的每个槽位。只读：写入请使用“固件槽位操作”标签页。`,"report.slot":`槽位`,"report.address":`地址`,"report.version":`版本`,"report.size":`大小`,"report.key":`密钥`,"report.accepts":`接受的密钥`,"report.footer":`尾部校验`,"report.bootable":`可启动`,"report.bytes":`{count} B`,"report.plaintext":`无（明文）`,"report.yes":`是`,"report.no":`否`,"report.notApplicable":`不适用`,"report.slotReason":`{slot}：{reason}`,"report.writing":`写入`,"report.noBankWritten":`这台相机的任何槽位都不会被写入：`,"report.oneBank.plain":`一次一个槽位：“固件槽位操作”标签页一次写入或修补这台相机的一个槽位，每个槽位都以明文暂存（镜像原样，不使用密钥），每次写入前都会先征求确认。`,"report.oneBank.slotKeystream":`一次一个槽位：“固件槽位操作”标签页一次写入或修补这台相机的一个槽位，每个槽位都以其镜像自身的密钥块 0 暂存，每次写入前都会先征求确认。`,"report.oneBank.keyA":`一次一个槽位：“固件槽位操作”标签页一次写入或修补这台相机的一个槽位，每个槽位都以由当前启动槽位和正在运行的应用程序推导出的密钥暂存，每次写入前都会先征求确认。`,"report.oneBank.ffVendor":`一次一个槽位：“固件槽位操作”标签页一次写入或修补这台相机的一个槽位，每个槽位都按厂商应用暂存 16 Hz FF 镜像的方式暂存（镜像 XOR 其自身的密钥块 0），并由相机以密钥 B 存储，每次写入前都会先征求确认。`,"report.refusesEvery":`“固件槽位操作”标签页拒绝这台相机的所有槽位：`},decrypt:{"status.noFile":`未选择文件。`,"status.reading":`正在读取文件…`,"status.notUsable":`不是可用的闪存镜像。`,"status.building":`正在生成压缩包…`,"status.nothingDecrypted":`没有解密出任何镜像——原因请查看日志。清单文件已在你的下载中。`,"status.done":{other:`完成——已解密 {done}/{count} 个槽位。请查看你的下载。`},"offline.title":`解密你已有的闪存镜像`,"offline.description":`完整的闪存镜像，逐个槽位解密。`,"offline.intro":`4.x/Nano 标签页的第 2 步已经会解密它读取的所有内容，所以只有当你的闪存镜像来自别处——之前的运行、J-Link 或 SPI 编程器——时才需要这里。文件在本地读取，绝不上传。**这部分在所有浏览器中都能使用**，包括 Safari 和 iOS，因为它不需要 USB 访问。`,"offline.actions":`离线解密操作`,"offline.choose":`选择镜像文件…`,"offline.panel":`离线解密`,"offline.detectedTitle":`检测到的固件系列`,"offline.detectedIntro":`没有连接相机，所以固件系列是根据文件中的镜像本身评分得出的。无论哪种情况，密钥都是从每个槽位的密文中求出的；这里只决定报告中写的是哪个固件系列。`,"offline.scoreBasis":`根据文件中的镜像`,"slot.title":`解密一个固件槽位`,"slot.description":`来自文件的一个槽位：64 KB，与相机中的存储形式相同。`,"slot.intro":`选择一个存有单个固件槽位的文件——即一个 65,536 字节的槽位，就像在<link>{tab}</link>标签页导出槽位时保存的那样，或者完整闪存镜像中某个槽位地址处的 64 KB。本页会从该槽位自身的字节中找出密钥，解密镜像，并提供下载，同时显示密钥、大小和 SHA-256。不使用相机，所以不连接任何设备也能使用。`,"slot.refusedIntro":`如果文件不是一个槽位、不含固件镜像或无法解密，就会被拒绝并给出原因。已擦除的槽位会如实说明，没有可解密的内容。`,"slot.actions":`槽位文件操作`,"slot.choose":`选择槽位文件…`,"slot.decrypting":`正在解密 {file}…`,"slot.unreadable":`无法读取该文件。`,"slot.notDecrypted":`未解密：{file} 不是本页能解密的固件槽位。`,"slot.nothingWritten":`没有向任何地方写入任何内容。请选择一个 64 KB 的槽位文件，或在上面的部分中选择完整的闪存镜像。`,"slot.erased":`{file} 是一个已擦除的槽位。`,"slot.resultTitle":`已解密的固件槽位`,"slot.file":`文件`,"slot.fileSize":`文件大小`,"slot.fileSha":`文件的 SHA-256`,"slot.imageVersion":`镜像版本`,"slot.imageSize":`镜像大小`,"slot.imageSha":`镜像 SHA-256`,"slot.acceptanceSum":`校验和`,"slot.notComputed":`此形式不计算`,"slot.family":`固件系列`,"slot.familyDetected":`{name}（从镜像中检测得出）`,"slot.familyMismatch":`{name}——该和值不是此固件系列要求的校验目标值，所以引导程序不会按现状接受这个镜像`,"slot.unknown":`未知`,"slot.bytes":`{size} B`,"slot.key":`密钥`,"slot.keyPlain":`无：该槽位以明文存放镜像（2014 年的明文链）`,"slot.keyFfB":`1.3.0.8 FF 密钥对中的密钥 B`,"slot.storedAs":`存储形式`,"slot.storedAsFfB":`镜像与密钥 B 的密钥流异或（XOR），头部窗口保持原样`,"slot.keyNone":`无`,"slot.keyNamed":`{key}——{name}`,"slot.keyForm":`密钥形式`,"slot.keyFormOnce":`{k}——镜像本身恰好包含一次这种形式，由此确定`,"slot.keyFormDefault":`{k}——镜像中没有只出现一次的形式，因此显示该固件系列的默认值`,"slot.resultActions":`解密后镜像的操作`,"slot.download":`下载 {file}`,"slot.downloadFallback":`解密后的镜像`,"detection.detected":`检测结果`,"detection.score":`评分`,"detection.scoreText":`{score}（满分 1.00），{basis}`,"detection.readAs":`按此系列读取`,"detection.summary":`摘要`,"detection.why":`原因：`,"detection.ambiguous":`**证据不足以确定这是哪个固件系列。**要么得分最高者并不比通用后备方案更好，要么第二名与它太接近，无法判定。解密不受影响——无论哪种情况，密钥都是从密文中求出的——但报告中写的固件系列，以及任何依赖它的内容，都只是猜测。`},v4:{"status.starting":`正在开始…`,"status.building":`正在生成压缩包…`,"status.cancelling":`正在取消——将保存目前已读取的全部内容…`,"status.refused":`已拒绝——没有读取任何内容。请查看日志上方的消息。`,"status.sweepDone":`完成——已激活 {armed}/{total} 个选择器，其中 {withData} 个有数据。请查看你的下载。`,"status.sweepDoneCancelled":`完成——已激活 {armed}/{total} 个选择器，其中 {withData} 个有数据（已取消）。请查看你的下载。`,"status.dumpDone":`完成——已读取 {read}/{expected} 个窗口。请查看你的下载。`,"status.dumpDoneCancelled":`完成——已读取 {read}/{expected} 个窗口（已取消）。请查看你的下载。`,"status.dumpDoneIncomplete":`完成——已读取 {read}/{expected} 个窗口（不完整——请查看日志）。请查看你的下载。`,"refusal.generic":`相机与 4.x/Nano 固件系列不符，而此标签页只读取该系列。没有读取任何内容。对于 0.x 或 1.x 相机（2014 或 2016 年的版本），请使用“{tab}”。`,"refusal.otherFamily":`相机看起来是 {name}（{id}），不是 4.x/Nano 相机，而此标签页只读取 4.x/Nano。没有读取任何内容。对于 0.x 或 1.x 相机（2014 或 2016 年的版本），请使用“{tab}”。`,"refusal.legacyLine":`相机运行的是 {version}，属于 0.x 或 1.x 版本（2014 或 2016 年），而此标签页只读取 4.x/Nano。除版本外没有读取任何内容。对于 0.x 或 1.x 相机，请使用“{tab}”。`,"dump.title":`导出`,"dump.actions":`导出操作`,"dump.start":`开始导出`,"dump.panel":`导出`,"dump.how":"两种导出都会先询问相机运行的是什么固件：用 `{getInfo}` 读取它的版本——所有 Seek 版本对这个读取的应答方式都相同——并且只有当该版本可以通过 USB 读取时，才发送一个普通的和一个带令牌的 `{begin}`，以及一次读取。本页就是这样判断相机属于哪个固件系列的。此标签页只读取 4.x 和 Nano 系列。应答表明属于其他系列的相机，会在读取任何内容之前被拒绝，本页会指出适合它的标签页。不报告版本、或运行早于 0.8.0.0 的版本的相机，完全不会被读取，本页会说明原因。","dump.modes":"**开始导出**会读取该版本自身选择器表能访问到的每个块。下方*选项*中的**导出全部选择器**会探测 `{begin}` 的每个选择器 `{first}`–`{last}`，并保存每个选择器返回的内容——速度更慢，但也能获取精选映射跳过的块。","dump.sweep":`导出全部选择器（{first}–{last}）`,"dump.sweepNote":`探测每个选择器，并保存每个选择器返回的内容。比“开始导出”慢。`,"output.title":`你会得到什么`,"output.intro":"一个 `{ext}` 下载文件，包含：","output.caption":`下载的压缩包中的文件`,"output.file":`文件`,"output.what":`内容`,"output.flash":`拼合后的 4 MB 闪存镜像（空缺填充值和解锁令牌——如果用到——记录在 manifest.json 中）`,"output.windows":`每个 64 KB 块，保持传输时收到的原样`,"output.decrypted":`每个固件镜像槽位，已解密（如果找到了密钥）`,"output.reports":`每个槽位的报告：密钥、密钥位置、固件系列和加密方式、SP、入口地址、SHA-256`,"output.manifest":`精确的读取/空缺/解密元数据`,"output.readme":`这份采集是什么、有哪些局限`,"output.keyFromDump":`密钥是从导出的镜像本身恢复的，因此不需要密钥文件或设备机密。`,"output.bestEffort":`解密仍然是尽力而为。如果没有找到密钥——例如在引导程序从芯片 OTP 推导密钥的设备上，而 OTP 不在闪存镜像中——那个槽位就会被直接跳过，压缩包的其余部分不受影响。`,"readonly.title":`只读保证`,"readonly.intro":`本标签页只能发出恰好六个厂商命令。这就是它的全部词汇——没有任何代码路径能发出其他命令：`,"readonly.caption":`六个只读厂商命令`,"readonly.absent":"`{setData}`、`{complete}`、`{reset}` 以及所有上传、提交和擦除命令都不在此视图中。`{usbReset}` 也从不调用；重试路径只是关闭再重新打开句柄。解密完全在内存中、在你浏览器里的副本上进行，绝不触及设备。","readonly.writing":`写入相机的功能在另一个标签页<link>{tab}</link>中，它一次写入一个槽位，并在每次写入前征求确认。*此*标签页上的任何内容都无法发出那些命令。`,"readonly.firstReads":"在相机报告固件版本之前，六个命令中只会发送三个，而且只作为读取：`{getInfo}`、`{getMode}` 和 `{getError}`。在检查过的全部 36 个固件镜像中，这三个读取都位于相同的命令编号，含义也相同；同一个命令编号并非在每个版本上都含义相同，所以在确定版本之前不会发送任何其他命令。","gap.summary":`{address} 空缺`,"gap.where":"USB 命令集为 4 MB 闪存的每个 64 KB 块都提供了读取窗口选择器，唯独 `{range}` 除外。合并镜像中该块用 `{fill}` 填充，并记录在 `{manifest}` 中。","gap.costs":"**实际上这对你没有任何损失。**在大多数相机上，该块只是已擦除的闪存，读出来本来就是 `{fill}`——所以填充值与实际内容一致，镜像是完整的。","gap.redundant":"而当该块*确实*被使用时，其中存放的是一份冗余副本。这些相机会在多个 64 KB 槽位中保存同一个固件镜像：在制作本页时检查过的每一份多槽位镜像中，所有槽位解密后的固件都逐字节相同——其中一例是四个用两种不同密钥写入的槽位。在唯一一台在 `{address}` 处有真实镜像的设备上，它与 `{before}` 和 `{after}` 处的副本逐字节相同，所以压缩包中仍然包含该固件，只是从另一个地址读取的。","gap.fine":"这种冗余也说明了为什么 `{address}` 读出为 `{fill}` 的相机没有问题：可启动的固件仍存在于其他槽位中。无论如何，本标签页都不会向设备写入任何内容——这个空缺只影响你下载的文件。","gap.complete":`如果你确实需要严格完整、逐字节的镜像——比如要把闪存与参考镜像做比对——请通过 SWD/J-Link 或用 SPI 编程器读取。`,"opcodes.opcode":`操作码`,"opcodes.name":`名称`,"opcodes.dir":`方向`,"opcodes.why":`用途`,"opcodes.getInfo":`正在运行的固件版本，最先读取：它决定导出使用哪个版本的选择器表；不报告版本的相机不会被读取`,"opcodes.getError":`每一步之后检查状态`,"opcodes.setMode":`仅用于选择模式 0，且仅在当前不是该模式时`,"opcodes.getMode":`读取当前模式`,"opcodes.getData":`实际的闪存读取`,"opcodes.begin":`仅为易失性的读取窗口选择器——它选择接下来的读取返回哪个 64 KB 块，不写入任何内容`,"identity.versionUnknown":`未读取：相机没有说明它运行的是哪个固件。`,"identity.unsupported":`未读取：这台相机无法用这种方式读取。`,"identity.title":`检测到的相机`,"identity.firmware":`固件`,"identity.scoreBasis":`根据相机的应答，在读取任何槽位之前`,"options.title":`选项`,"options.subtitle":`——默认值是正确的；你无需更改这里的任何内容。`,"options.chunk":`chunk（control-IN 字节数）`,"options.gapFill":`gap-fill 字节`,"options.retries":`每个窗口的重试次数`,"options.retryDelay":`重试间隔（毫秒）`,"options.recipient":`recipient（控制传输接收方）`,"options.recipientAuto":`自动`,"options.recipientInterface":`interface（{requestTypes}）`,"options.recipientDevice":`device（{requestTypes}）`,"options.decrypt":`解密固件`,"options.yes":`是`,"options.no":`否`,"options.help":`**chunk** 是每次 control-IN 读取的大小，最大 64：即一个 EP0 包。当相机在低时钟下空闲时，更长的读取可能会被相机的启动 ROM 丢掉一个包，所以更大的值会按每次 64 字节读取；更小的值按设定使用，如果相机停滞，本页会自动改用更小的值并继续。**gap-fill** 是写入 USB 无法访问的那个 64 KB 块中的字节。**recipient** 默认为 interface，如果浏览器无法占用接口 0，则退而使用 device——固件两者都接受。`,"options.chunkRange":`chunk 必须在 1 到 {max} 之间，当前为 {value}`,"options.gapFillByte":`gap-fill 必须是单个字节，当前为 {value}`,"options.retriesMin":`重试次数必须为零或更多，当前为 {value}`,"options.retryDelayMin":`重试间隔必须为零或更多，当前为 {value}`},slots:{"section.title":`固件槽位操作`,"section.badge":`会写入闪存`,"section.description":`“读取槽位”会询问相机运行的是什么固件，读取它的三个固件槽位——{a}、{b} 和{r}——并显示每个槽位存放的内容。读取和导出不会改变任何东西。写入按钮在发送任何字节之前都会先征求确认。`,"section.danger":`**本页可以写入相机的闪存。**一次写入会擦除一个 64 KB 槽位，再写入新内容。结构上有效但无法运行的镜像会让相机无法启动，而引导程序不支持 USB——只有 SWD/J-Link 或 SPI 编程器才能恢复它。请先导出该槽位，并保存好文件。`,"actions.toolbar":`槽位操作`,"actions.read":`读取槽位`,"run.label":`槽位`,"empty.connected":`请按“读取槽位”。会先询问相机运行的是哪个版本；在本页不支持的版本上，不会打开任何读写窗口。`,"empty.disconnected":`请连接相机，然后按“读取槽位”。`,"unsupported.title":`此处不支持这个版本，因此没有读取任何槽位，也不能写入任何槽位。`,"refusal.notIdentified.title":`无法识别：本页无法判断相机运行的是哪个版本。`,"refusal.notIdentified.body":`相机没有给出可用的固件版本，因此没有读取任何槽位，也没有打开任何读写窗口。本页适用于 {minVersion} 及更新的版本。早于 {minVersion} 的版本不在槽位页面的支持范围内，所以运行这些版本的相机永远不会在这里被读取。`,"refusal.notIdentified.hint":`如果相机运行的是受支持的版本，它可能只是还在启动。{hint}`,"refusal.title":`已拒绝——没有打开任何读写窗口。`,"status.reading":`正在读取…`,"status.readingAgain":`正在重新读取槽位…`,"status.read":{other:`已读取。共 {count} 个槽位，已读取 {read} 个。`},"status.unsupported":`此版本不受支持——没有读取任何槽位。`,"status.refused":`已拒绝——没有打开任何读写窗口。请查看日志下方的消息。`,"status.disconnected":`设备已断开——请重新读取槽位。`,"status.newDevice":`已选择新设备——请重新读取槽位。`,"status.dumping":`正在导出{bank}…`,"status.dumped":`已导出{bank}。`,"status.readingImage":`正在读取镜像…`,"status.ready":`准备就绪——请检查计划，然后写入。`,"status.rejected":`已拒绝——请查看上方的日志。`,"status.writing":`正在写入…`,"status.patching":`正在修补{bank}…`,"status.patchingEvery":`正在修补所有槽位…`,"status.written.mismatch":`已写入，但回读结果不一致——请查看结果。`,"status.written.verified":`已写入。该槽位的回读结果与写入内容一致。`,"status.written.notCompared":`已写入。回读结果未经比对——请查看结果。`,"status.patched.unexpected":`已修补，但回读结果的差异不只是计划中的那些——请查看结果。`,"status.patched.ok":`已修补。该槽位的回读结果与计划相符。`,"status.patched.unchecked":`已修补。回读结果未经检查——请查看结果。`,"status.every.stopped":{other:`在{bank} 处停止——已修补 {count} 个槽位；请查看结果。`},"status.every.unchecked":{other:`已修补 {count} 个槽位，但有一次回读未按计划检查——请查看结果。`},"status.every.ok":{other:`已修补 {count} 个槽位。每个槽位的回读结果都与计划相符。`},"status.cancelled.nothing":`已取消——没有写入任何内容。`,"status.cancelled.one":`在向{bank} 发送提交命令之后取消——该槽位可能只写入了一部分。在依赖它之前，请先读取它。`,"status.cancelled.many":`在向{banks} 发送提交命令之后取消——每个槽位都可能只写入了一部分。在依赖它们之前，请先读取它们。`,"gate.connectFirst":`请先连接相机。`,"gate.busy":`另一项操作正在进行——请等待它完成。`,"gate.readFirst":`请先读取槽位。`,"gate.cameraRefused":`由于上方横幅中所述的原因，无法从这里写入这台相机。不会发送任何内容。`,"gate.notRead":`未读取：{reason}。写入之前请重新读取槽位。`,"gate.notReadNoReason":`未读取：这个槽位没有被读取。写入之前请重新读取槽位。`,"gate.emptyNotWritable":`这个槽位是空的，在此版本上无法写入：{reason}`,"gate.noSuchBank":`此版本没有这个槽位。`,"table.caption":`这台相机上的每个固件槽位——{a}、{b} 和{r}——在浏览器中读取并检查的结果`,"table.col.bank":`槽位`,"table.col.firmware":`固件`,"table.col.size":`大小`,"table.col.key":`密钥`,"table.col.bootable":`可启动`,"table.col.sha":`明文的 SHA-256`,"table.col.actions":`操作`,"table.notRead":`未读取——{reason}`,"table.notReadNoReason":`未读取——该槽位没有被读取`,"table.empty":`空`,"table.emptyNote":`没有镜像：这个槽位的头部窗口读出全是 0xFF，因此不会从中解密任何内容，写入它也不会覆盖任何固件。`,"table.emptyWritable":`可以写入。{why}`,"table.emptyNotWritable":`在此版本上无法写入：{reason}`,"table.unknownVersion":`版本未知`,"table.imageId":`镜像 {id}`,"table.noImage":`无镜像`,"table.bankSize":`槽位 {size} B`,"table.imageSize":`镜像 {size} B`,"table.keyNone":`无（明文）`,"table.boot.empty":`——没有可启动的内容`,"table.boot.bootable":`可启动——引导程序接受它`,"table.boot.notBootable":`不可启动——启动时会被跳过`,"table.boot.recoveryOnly":`仅作恢复——当 {letterA} 和 {letterB} 中都没有引导程序接受的内容时，才会运行 {letterR}（这是在一台相机上针对此镜像的较早形式测得的）；这种形式能否启动尚未测试`,"table.boot.unknown":`未知——{why}`,"table.dump":`导出`,"table.flashPlain":`写入解密后的镜像…`,"table.flashRaw":`写入原始字节…`,"table.restore":`从完整闪存备份还原（.bin 或 .zip）…`,"table.makeFps":`改为 {hz} FPS`,"table.copyTo":`复制到{bank}`,"table.copyOff":`{button}：{reason}`,"table.copyOffNoReason":`{button}：不可用`,"table.copyNote":`把这个槽位中的固件（按本次读取的解密结果）复制到你选择的槽位，无论那个槽位现在存放着什么。在发送任何内容之前，你会先检查计划。`,"table.restoreNote":`选择一个完整的闪存备份：一个 .bin（完整的 4 MB 闪存镜像，例如用 J-Link 读出的），或包含这种镜像的 .zip（Preserve 运行文件，或“导出并解密 4.x/Nano”或“导出全部选择器”保存的 zip）。会从中截取出这个槽位并解密，在发送任何内容之前以计划的形式显示。`,"table.fpsNote":`通过修改字节，把这个槽位从 {fromHz} Hz 提高到 {toHz} Hz。会先把该槽位保存为一个 zip 下载，其中的解密文件就是恢复原状的途径。`,"table.risk.bootedRecovery":`{booted}，且是恢复槽位：写入它需要额外确认。`,"table.risk.booted":`{booted}：写入它需要额外确认。`,"table.risk.recovery":`{bank}：写入它需要额外确认。`,"table.risk.bootUnnamed":`相机没有说明它从哪个槽位启动：写入它需要额外确认。`,"fps.applied":`已应用帧率补丁：此镜像以 {hz} Hz 运行。`,"fps.earlierPatch":`不提供帧率补丁：这个槽位中是较早的、不含 USB 修复的 {hz} Hz 补丁。请先还原原厂镜像，再按“改为 {hz} FPS”。`,"fps.atRate":`无需帧率补丁：此版本本来就以 {hz} Hz 运行。`,"fps.notOffered":`不提供帧率补丁：{reason}`,"fps.readFirst":`请先读取槽位——补丁是根据该槽位自身的镜像规划的`,"everyBank.toolbar":`所有槽位`,"everyBank.make":`所有槽位改为 {hz} FPS`,"everyBank.faster":`让所有槽位更快`,"everyBank.note":`只需一次确认，依次修补{order}；每个槽位都会先保存到同一个 zip 下载中，写入后再回读。`,"everyBank.noteBootedLast":`只需一次确认，依次修补{order}，相机当前启动的槽位放在最后；每个槽位都会先保存到同一个 zip 下载中，写入后再回读。`,"what.copy":`{bank} 的镜像`,"what.restore":`{file} 中的{bank}`,"preview.title":`已为{bank}（{address}）准备好写入`,"preview.file":`文件`,"preview.source":`镜像来源`,"preview.target":`目标`,"preview.targetEmpty":`{bank} 是空的：其中没有镜像，所以这次写入不会覆盖任何固件`,"preview.readAs":`文件识别为`,"preview.readAs.ff":`解密后的 {version} FF 镜像`,"preview.readAs.plain":`解密后的镜像`,"preview.readAs.raw":`原始字节`,"preview.staging":`暂存方式`,"preview.key":`密钥`,"preview.payload":`载荷`,"preview.payloadValue":{other:`{size} B，分 {count} 块发送，每块最多 {chunk} B`},"preview.checksum":`传输校验和`,"preview.stored":`写入后存储的内容`,"preview.storedNotPredicted":`无法预测——以回读结果为准`,"preview.storedPredicted":`预计 {size} B`,"preview.storedKeyB":`预计 {size} B——是镜像与密钥 B 异或的结果，而不是载荷本身`,"preview.savedFirst":`先行保存`,"preview.compareCaption":`{bank} 中会改变的内容`,"preview.col.field":`字段`,"preview.col.now":`当前`,"preview.col.after":`写入后`,"preview.readFirst":`写入前请阅读：`,"preview.note":`注意：{note}`,"preview.nothingSent":`尚未向相机发送任何内容。写入时会把这些载荷传送到{bank}并提交。`,"preview.toolbar":`{bank} 的写入操作`,"preview.write":`写入{bank}…`,"preview.discard":`放弃`,"writeConfirm.title":`将 {what} 写入{bank}（{address}）？`,"writeConfirm.booted":`{bootsNow}。写入它会替换相机当前正在运行的固件。如果新镜像无法运行，相机可能完全无法启动。`,"writeConfirm.recovery":`{bank} 是恢复槽位，即引导程序最后退回使用的那份副本。写入它之后，在还原之前相机将没有这份副本。`,"writeConfirm.bootUnnamed":`相机没有说明它从哪个槽位启动，因此{bank} 被视为它当前启动的槽位。写入它可能会替换相机正在运行的固件。`,"writeConfirm.empty":`{bank} 是空的：其中没有镜像，所以不会覆盖任何固件。`,"writeConfirm.eraseEmpty":`这次写入仍会擦除相机闪存中{bank} 处的 64 KB 块（本来就是空白的），再写入新内容。`,"writeConfirm.erase":`这会擦除相机闪存中的一个 64 KB 块，并在{bank} 处写入新内容。`,"writeConfirm.keyLine":`镜像写入时使用的密钥：{key}。其他每个槽位也以同样的方式写入。`,"writeConfirm.backup":`在发送任何内容之前，会重新读取{bank}，并保存为一个 zip 下载：{file}。请在下载文件夹中确认它已存在。`,"writeConfirm.noReset":`不会发送重置命令。写入后请拔下相机再重新插上，该槽位才会生效。`,"writeConfirm.noUsbRecovery":`如果镜像无法运行，相机将无法通过 USB 恢复——只能用 SWD/J-Link 或 SPI 编程器恢复。`,"writeConfirm.ackUnnamed":`我明白相机没有说明它从哪个槽位启动，因此这个槽位被视为当前启动的槽位；我也明白，有问题的镜像可能导致相机无法启动。`,"writeConfirm.confirm":`是——写入{bank}`,"ack.booted":`我明白这是相机当前启动的槽位，有问题的镜像可能导致相机无法启动。`,"ack.recovery":`我明白这是恢复槽位，有问题的镜像会让相机失去最后的备用副本。`,"fpsConfirm.title":`让{bank} 以 {hz} FPS 运行？`,"fpsConfirm.booted":`{bootsNow}。打过补丁的镜像会替换它当前运行的固件。`,"fpsConfirm.recovery":`{bank} 是恢复槽位，即引导程序最后退回使用的那份副本。`,"fpsConfirm.what":`{bank} 中存放的是固件 {version}，这会让它的镜像以 {toHz} Hz 运行，而不是 {fromHz} Hz。`,"fpsConfirm.unknownVersion":`（未知）`,"fpsConfirm.bytes":{other:`补丁会改变镜像中的 {count} 个字节以及校验和字，使引导程序检查的校验和保持不变。密钥对不会被改动。`},"fpsConfirm.wayBack":`那个 zip 中的解密文件就是恢复原状的途径：要撤销补丁，请在{bank} 上用“写入解密后的镜像”写入它。`,"fpsConfirm.noReset":`不会发送重置命令。写入后请拔下相机再重新插上，打过补丁的槽位才会生效。`,"fpsConfirm.ackUnnamed":`我明白相机没有说明它从哪个槽位启动，因此这个槽位被视为当前启动的槽位。`,"fpsConfirm.confirm":`是——修补{bank}`,"fpsEvery.title":`让所有槽位以 {hz} FPS 运行？`,"fpsEvery.titleMixed":{other:`修补 {count} 个槽位的帧率？`},"fpsEvery.intro":{other:`这会修补 {count} 个可用该补丁的槽位（固件 {version}）：`},"fpsEvery.role.bootedRecovery":`{bank}（相机当前启动的槽位，也是恢复槽位）`,"fpsEvery.role.booted":`{bank}（相机当前启动的槽位）`,"fpsEvery.role.recovery":`{bank}（恢复槽位，即最后的备用副本）`,"fpsEvery.role.bootUnnamed":`{bank}（相机没有说明它从哪个槽位启动）`,"fpsEvery.offer":{other:`{bank}：{fromHz} Hz 改为 {toHz} Hz，改动 {count} 个字节和校验和字。`},"fpsEvery.other":`{bank}：{note}`,"fpsEvery.others":`保持不变：{others}`,"fpsEvery.orderOne":`它只写入{bank}，并回读检查。`,"fpsEvery.order":`它们按以下顺序写入：{order}。每个槽位都会在写下一个之前回读，第一次失败就会停止其余的写入。`,"fpsEvery.orderBootedLast":`它们按以下顺序写入：{order}。相机当前启动的槽位放在最后，因此一旦失败，会在写到它之前停止。每个槽位都会在写下一个之前回读，第一次失败就会停止其余的写入。`,"fpsEvery.wayBack":`那个 zip 中的解密文件就是恢复原状的途径：要撤销某个槽位的补丁，请在该槽位上用“写入解密后的镜像”写入它对应的文件。`,"fpsEvery.noReset":`不会发送重置命令。写入后请拔下相机再重新插上，打过补丁的槽位才会生效。`,"fpsEvery.ack":`我明白这会写入{banks}，有问题的镜像可能导致相机无法启动。`,"fpsEvery.confirm":{other:`是——修补 {count} 个槽位`},"outcome.verified":`{bank}——{what}：该槽位的回读结果与写入内容一致。`,"outcome.mismatch":`{bank}——{what}：回读结果与写入的内容并不一致。`,"outcome.notCompared":`{bank}——{what}：已回读，但没有比对，因此这次写入在这里未经验证。`,"outcome.commitStatus":`相机的提交返回状态 {status}。`,"outcome.wasEmpty":`{bank} 在这次写入之前是空的，所以没有覆盖任何固件。`,"outcome.provenVerified":`目前已证实：载荷已传送并提交，该槽位的回读结果与写入内容一致。尚未证实：引导程序是否会选择这个槽位，镜像是否能够运行。`,"outcome.provenCommitted":`目前已证实：载荷已传送并提交。尚未证实：引导程序是否会选择这个槽位，镜像是否能够运行。`,"outcome.replug":`**现在请拔下相机，再重新插上。**没有发送重置命令，所以该槽位只有在真正断电重启之后才会生效。然后重新读取槽位：只有相机报告的版本和活动槽位才能最终说明结果。`,"outcome.replugShort":`**现在请拔下相机，再重新插上。**没有发送重置命令。然后重新读取槽位。`,"outcome.savedFirst":`已先行保存为下载文件：{file}。`,"outcome.wayBackOne":`其中的解密文件就是恢复原状的途径（在同一个槽位上使用“写入解密后的镜像”）。`,"outcome.wayBackMany":`其中的解密文件就是恢复原状的途径（在各个槽位上使用“写入解密后的镜像”）。`,"outcome.checkDownloads":`请在下载文件夹中确认它已存在。`,"fpsOutcome.title":`{bank}——已从 {fromHz} Hz 修补为 {toHz} Hz（固件 {version}）。`,"fpsOutcome.readBackOk":{other:`回读结果与保存的镜像相比，只在计划中的 {count} 个字节（补丁位置和校验和字）处不同。`},"fpsOutcome.readBackBad":{other:`回读结果的差异并不只是计划中的那些：有 {unexpected} 个字节发生了意外改变，{count} 个应改变的字节没有改变。`},"fpsOutcome.notTaken":`没有进行回读，因此这里没有检查补丁。`,"fpsEveryOutcome.title":{other:`所有槽位：已修补 {count} 个中的 {done} 个，顺序为：{order}。`},"fpsEveryOutcome.readBackOk":{other:`回读结果与保存的槽位相比，只在计划中的 {count} 个字节处不同。`},"fpsEveryOutcome.notTaken":`没有进行回读。`,"fpsEveryOutcome.stopped":`已停止：{reason}。`,"fpsEveryOutcome.notWritten":`未写入：{banks}。`,"keys.refusedTitle":`无法从这里写入这台相机的任何槽位。`,"keys.title":`写入所用的密钥`,"keys.chain":`固件链`,"keys.chainPlain":`2014 年的明文链：每个槽位都以明文存储，因此都不含密钥`,"keys.writtenAs":`写入形式`,"keys.writtenPlain":`镜像原样写入，不使用密钥，可写入任何槽位`,"keys.stagedAs":`暂存为`,"keys.storedAs":`存储为`,"keys.refused":`已拒绝`,"keys.bootedBank":`当前启动的槽位`,"keys.bootedHolds":`{bank} 持有{key}`,"keys.theBootedBank":`当前启动的槽位`,"keys.unnamedKey":`本页无法命名的密钥`,"keys.bootedBanksKey":`当前启动槽位的密钥`,"keys.writtenDerived":`{line}；每个槽位都以同样的方式写入`,"how.title":`这些按钮的作用`,"how.read":`**读取槽位**和**导出**不会改变相机中的任何内容。在做任何其他事情之前，会先询问相机运行的是哪个版本；早于 {minVersion} 的版本会被报告出来，其槽位不会被读取。`,"how.flash":`**写入解密后的镜像**接收一个明文镜像，在暂存之前按该槽位固件的要求加密，并显示计划。**写入原始字节**则完全按原样暂存文件。在你确认之前，两者都不会发送任何内容。`,"how.ff":`运行 1.3.0.8 的 Compact 可能是 8 Hz 版本，也可能是 16 Hz FF 版本，两者报告的版本号相同。相机自己能区分它们：它对每个槽位的应答会说明当前应答的应用程序是否接受该槽位，而每个版本会给出什么应答都可以预测。8 Hz 镜像可以写入任何槽位。FF 镜像按厂商应用的方式暂存（镜像 XOR 密钥 A），16 Hz 版本会以密钥 B 存储它，可写入任何槽位。本页不会拒绝它：在你确认之前，计划会说明预计相机会如何处理它（8 Hz 版本会在提交时拒绝它；其他版本的相机会按发送的原样写入，但无法从中启动）。FF 镜像能否启动尚未测试：资料库中没有这个版本的真实引导程序。写入恢复槽位 {letterR} 时，和任何恢复槽位的写入一样需要额外确认。**空**槽位（其头部窗口读出全是 0xFF，就像许多 2014 年相机的{b}）是一种状态，而不是故障。导出时它就是原始的 64 KB 0xFF，没有可解密的内容；它的写入方式与其他槽位完全相同，计划和确认对话框会说明不会覆盖任何固件。`,"how.copy":`槽位行上的 **{copyA}**、**{copyB}** 和 **{copyR}** 会把该槽位中的固件（按本次读取的解密结果）写入另一个槽位，无论那个槽位现在存放着什么。镜像的暂存方式与任何解密后的镜像相同，所以计划和确认都与写入文件时一样。**从完整闪存备份还原**接收一个 .bin（完整的 4 MB 闪存镜像，例如用 J-Link 读出的）或包含这种镜像的 .zip（Preserve 运行文件，或“导出并解密 4.x/Nano”或“导出全部选择器”保存的 zip），从中截取出这个槽位，解密并显示计划；如果备份看起来来自另一台相机或另一个固件，计划中会说明。在备份中为空的槽位，或导出时没有读到的槽位，无法通过写入来还原，本页会说明这一点。`,"how.fps":`槽位行上的**改为 N FPS**会把该槽位的镜像修改为更高的帧率；**所有槽位改为 N FPS**则只需一次确认，对每个可用该补丁的槽位都这样修改，相机当前启动的槽位放在最后。对于不能使用该补丁的槽位，页面会说明原因。`,"how.backup":"**每次写入都会先保存该槽位**：重新读取该槽位，并保存为一个 zip 下载，文件名包含时间、相机序列号、固件、槽位和写入操作（例如 `{example}`），其中有槽位的存储内容、解密后的镜像，以及说明每个文件是什么的备注。写入会等到下载开始之后才进行。浏览器不会告诉你下载何时真正写入磁盘，所以请检查你的下载文件夹。要恢复原状，请用**写入解密后的镜像**写入 zip 中的解密文件。","how.write":"一次写入会擦除一个 64 KB 槽位，再写入新内容。位于 `{address}` 的引导程序和启动配置在这里永远不会被写入，也没有用于选择活动槽位的控件。只有在拔下相机再重新插上之后，该槽位才会生效。"},preserve:{"how.title":`会发生什么`,"how.descriptionIdle":`连接相机，然后从步骤 02 开始。`,"how.descriptionRun":`运行 {runId}。`,"how.descriptionRunVersion":`运行 {runId}——固件 {version}。`,"how.restarts":`相机在每个步骤中都会**重启**。重启后 Chrome 不再认得它（它没有 USB 序列号），所以本页会请你按**连接设备**并再次选择相机。这是正常流程——你完成后，该步骤会自动继续。`,"how.noFile":`不需要选择任何固件文件：所有内容都从相机本身读取。`,"how.banks":`相机把固件保存在三个**槽位**中（{a}、{b} 和{r}）。步骤 02 会读取全部三个槽位，并判断相机下次从哪个槽位启动；只有那个槽位中有补丁时，补丁才会起作用。由你选择步骤 03 修补哪些槽位——默认是下次启动进入的那个——步骤 04 会把它们全部还原。`,"how.runFile":"每个步骤之后，浏览器都会下载一个**运行文件**，文件名包含本次运行的开始时间、保存时间和已到达的步骤（`{example}`），其中每个步骤一个文件夹。请保留最新的那个——它可以让你以后继续。","how.writeWarning":`**步骤 03 和 04 会写入相机的闪存**，每一步都会先请你确认。在其中任一步骤运行期间，请保持相机连接（除非本页要求你重新插拔），并让电脑保持唤醒，最好接上电源。写入一旦中断，相机就只能用硬件编程器（SPI 或 SWD/J-Link）修复。`,"how.phone":`**在手机上：**在步骤 03 之前，打开飞行模式并关闭 Wi-Fi 和移动数据，以免来电或通知在写入过程中把浏览器切走——并保持屏幕常亮。页面打开后可以离线继续工作。`,"how.pastCommit":`**本次运行没有写入的记录，因此之后的步骤已关闭。**相机可能已经在运行打过补丁的镜像（写入被中断），也可能没有（写入从未开始）——运行文件无法证明是哪一种。在没有写入记录的情况下，不要对已打补丁的相机执行全闪存读取或还原；正确的做法是步骤 03，它在写入前的检查会读取槽位，并拒绝盲目地再次写入。只有当该检查已经以 *already holds the patched bytes*（“已含有补丁字节”）拒绝时，才适用跳过——而且要通过它自己的对话框。`,"phase.readBuild.label":`读取并生成`,"phase.readBuild.inSentence":`读取并生成`,"phase.readBuild.description":`读取原厂相机允许读出的全部内容——31 个 64 KB 块——作为你的备份保存，再把每个固件槽位读取第二遍，判断相机下次从哪个槽位启动，并准备下一步要写入的小补丁。不会向相机写入任何内容。通常不到一分钟。如果相机中途需要重启，本页会请你按“连接设备”并再次选择它——这是预料之中的。`,"phase.patchDump.label":`写入并读取全闪存`,"phase.patchDump.inSentence":`写入并读取全闪存`,"phase.patchDump.description":`把一个小的临时补丁写入步骤 02 中选定的固件槽位（默认是相机下次启动的那个槽位），使相机能读出它的全部闪存。然后相机会重启——本页提示时，请按“连接设备”并再次选择它——接着读取整个 4 MB 闪存。步骤 04 会把原始固件放回去。`,"phase.restoreVerify.label":`还原并验证`,"phase.restoreVerify.inSentence":`还原并验证`,"phase.restoreVerify.description":`把你的原始固件写回去，重启相机（提示时请按“连接设备”并再次选择它），然后把所有内容再读一遍，检查它与备份是否逐字节一致。`,"step.backup.description":`读取原厂相机能读取的 31 个 64 KB 块，然后把每个槽位再读一遍（两次读取必须逐字节一致），从相机存储的内容中取出每个槽位的固件（加密存储的会先解密）并加以检查，再判断相机下次从哪个槽位启动。这是本次运行对这台相机的唯一一份副本，在写入任何内容之前获取。`,"step.patch.description":`离线进行，不使用相机。为本次运行可以写入的每个槽位生成补丁：它让相机的读取能访问整个 4 MB 闪存，并且以相机存储的形式写入，所以只有补丁本身的字节会改变。`,"step.commit.description":`写入。先回读每个选定的槽位，只有当每个槽位仍然是备份记录的内容时才会写入（已经完成的写入绝不会重复），然后逐个写入，相机最先尝试的槽位放在最后。这里不会重启相机：下一步会重启它。`,"step.drain.description":`重启相机，让它启动打过补丁的固件（它会大约十秒没有响应；本页会等待并重新找到它），检查它是从哪个槽位启动的（如果是没有补丁的槽位，该步骤会在读取任何内容之前停止），然后一次读取整个 4 MB 闪存，并把备份中每个已写入槽位的原始固件放进保存的镜像中。不会写入任何内容。`,"step.restore.description":`另一次写入。在打过补丁的固件仍在运行时，把每个已写入槽位的原始固件写回去，然后重启相机。`,"step.verify.description":`在重新启动之后，再次读取这 31 个块，其中包括每个槽位：0 个不同字节即证明相机的闪存与备份逐字节相同。只读。`,"phase.start":`开始{phase}`,"phase.retry":`重试{phase}`,"phase.goRestore":`继续步骤 04：还原槽位`,"phase.jumpOnly":`跳过未记录的写入继续运行`,"phase.skipWrite":`跳过写入——从全闪存读取开始`,"phase.toolbar":`{phase}操作`,"badge.writes":`会写入相机`,"badge.running":`正在运行`,"badge.done":`完成`,"badge.plannedStop":`按计划停止——接下来是还原`,"badge.failed":`已停止——请查看日志`,"badge.upNext":`下一步`,"notReady.noRun":`步骤 02 之后可用——它会开始本次运行。`,"notReady.previous":`步骤 {step}（{phase}）之后可用。`,"notReady.gate":`尚未就绪——{reason}。`,"phase.pastCommit":`适用于写入没有记录的情况——相机可能已经打过补丁。请参阅“{section}”下的说明。`,"phase.noDrain":`全闪存读取尚未运行——此步骤会在没有它的情况下让相机恢复原样。除非全闪存读取对你无关紧要，否则请先运行步骤 03。`,"phase.keepPlugged":`在此步骤完成之前，请保持相机连接，并让电脑保持唤醒。`,"phase.stepsLabel":`进度`,"phase.showDetails":`在日志中显示详细信息`,"phase.inDetail":`此步骤的详细内容`,"yourTurn.toolbar":`轮到你了`,"yourTurn.reconnect.title":`轮到你了：请按“连接设备”并选择相机。`,"yourTurn.reconnect.body":`相机已按计划重启。Chrome 自己无法再次认出它（它没有 USB 序列号），所以需要你再选择一次。你选择后，该步骤会立即继续。`,"yourTurn.replug.title":`轮到你了：请拔下相机，再重新插上，然后按“连接设备”。`,"yourTurn.replug.body":`本次运行的补丁是在读取修复之前制作的，因此在还原之前，相机需要重新上电。运行文件已经保存。`,"yourTurn.replugBeforeRestore.title":`步骤 04 之前：请拔下相机，再重新插上，然后按“连接设备”。`,"yourTurn.powerCycle.title":`轮到你了：请拔下相机，再重新插上，按“连接设备”——然后重试。`,"yourTurn.powerCycle.body":`相机的读取功能需要重新上电后才能再次读取。本次运行仍保留在页面中；没有丢失任何内容。`,"yourTurn.powerCycleAssert.title":`轮到你了：请拔下相机，再重新插上，按“连接设备”——然后继续。`,"yourTurn.powerCycleAssert.body":`上一次备份尝试已停止，相机需要重新上电后才能再次运行。相机自己无法报告这一点，所以由下方的按钮告诉本页你已经完成。`,"yourTurn.replugged":`我已重新插拔——继续{phase}`,"banks.title":`步骤 03 修补哪些槽位`,"banks.bootWord":`启动配置字`,"banks.lastStart":`上次启动`,"banks.nextStart":`下次启动`,"banks.caption":`步骤 02 读取到的三个固件槽位`,"banks.col.bank":`槽位`,"banks.col.address":`地址`,"banks.col.holds":`存放的内容`,"banks.nextStartBadge":`下次启动`,"banks.choiceLabel":`要修补的槽位`,"choice.nextStart":`下次启动进入的槽位`,"choice.all":`所有槽位`,"choice.withBanks":`{choice}——{banks}`,"choice.notOffered":`{choice}——不提供`,"banks.notChosen":`尚未选择槽位：{what}。请在上方按名称选择一个槽位。`,"banks.writes":`步骤 03 会写入{what}。`,"banks.fixed":`写入已经运行，因此选择已固定：步骤 04 只会还原这些槽位。`,"banks.notOfferedLine":`{choice}：不提供——{why}。`,"banks.refusedNoRun":`没有正在进行的运行——步骤 02 会开始一次`,"banks.refusedBusy":`有步骤正在运行——请在它完成后再选择槽位`,"plan.summary":`计划——{build}，修补{banks}`,"plan.summaryNone":`计划——{build}，尚未选择槽位`,"plan.yourCamera":`你的相机`,"plan.intro":`根据相机自身的字节生成。在步骤 03 运行之前不会写入任何内容，步骤 04 会把它写入的每个字节都还原。`,"plan.build":`构建`,"plan.version":`固件版本`,"plan.written":`写入`,"plan.route":`去向`,"plan.restore":`还原`,"plan.wholeFlash":`全闪存读取`,"plan.outro":`在相机存储的形式中，改变的正是这些字节，没有其他字节改变，所以相机固件的变化恰好就是这些差异，别无其他。`,"bankPlan.label":`{bank} 的补丁`,"bankPlan.titleChosen":`{bank}——由本次运行写入`,"bankPlan.titleNotChosen":`{bank}——未选择`,"bankPlan.source":`镜像来源`,"bankPlan.sourceValue":`{bank} 的存储内容`,"bankPlan.sourceTwoReads":`{bank} 的存储内容，两次读取一致（sha256 {sha}）`,"bankPlan.edit":`镜像修改`,"bankPlan.editValue":`原厂镜像上的 {label}（{id}）。它的平衡值 {balance} 位于调整字中；补丁在此基础上再做平衡，步骤 04 会把镜像连同这项修改一起还原。`,"bankPlan.factorySha":`原厂明文 sha256`,"bankPlan.patchedSha":`补丁后 sha256`,"bankPlan.diffCount":`闪存芯片上改变的字节`,"bankPlan.staged":`暂存长度`,"bankPlan.stagedValue":{other:`{size} B，分 {count} 块`},"bankPlan.rebalance":`平衡字`,"bankPlan.rebalanceValue":`{word}（原为 {balance}，即该修改的平衡值）`,"bankPlan.caption":`补丁在{bank} 中改变的确切字节`,"bankPlan.col.what":`改变的内容`,"bankPlan.col.offset":`偏移`,"bankPlan.col.before":`之前`,"bankPlan.col.after":`之后`,"verify.ok":{other:`**验证通过——完全一致。**重新启动后再次读取了相机：{read}/31 个块，{count} 个不同字节。它的闪存与第一次写入之前完全相同。`},"verify.okShort":{other:`**验证通过——完全一致。**重新启动后再次读取了相机：{read}/31 个块，{count} 个不同字节（不完整的块：{blocks}）。它的闪存与第一次写入之前完全相同。`},"verify.failed":`**检查发现与备份存在差异。**{error}`,unknownReason:`未知原因`,"confirm.titleWrite":`{phase}——写入{banks}？`,"confirm.titleJump":`{phase}——跳过未记录的写入？`,"confirm.chosenBanks":`选定的槽位`,"confirm.jump":`本次运行没有写入记录，而你是在声明这些写入已经完成、只是没有留下检查点：该步骤会跳过写入开始，而不是再写一次。各步骤自己的检查仍会运行——版本读取、槽位检查——猜错的代价是白白浪费一次全闪存读取，而不会让相机变砖。`,"confirm.jumpKeepPlugged":`在该步骤完成之前，请保持相机连接，并让电脑保持唤醒。`,"confirm.patch":`这会把一个小补丁写入{banks}。步骤 04 会把原始固件放回去。随后的全闪存读取只读不写。`,"confirm.patchInOrder":`这会按顺序把一个小补丁写入{banks}——相机最先尝试的槽位放在最后。步骤 04 会把原始固件放回去。随后的全闪存读取只读不写。`,"confirm.restore":`这会把你的原始固件写回{banks}。`,"confirm.restoreInOrder":`这会按顺序把你的原始固件写回{banks}——相机最先尝试的槽位放在最前。`,"confirm.keepPlugged":`写入期间请保持相机连接，并让电脑保持唤醒——写入一旦中断，相机就只能用硬件编程器（SPI 或 SWD/J-Link）修复。在手机上，请打开飞行模式并保持屏幕常亮。随后相机会重启；本页提示时，请按“连接设备”并再次选择它。这是预料之中的。`,"confirm.yesJump":`是——跳过写入`,"confirm.yesWrite":`是——写入相机`,"summary.proof":`证明`,"summary.complete":`完整镜像（4 MB）`,"summary.notProduced":`未生成`,"summary.differs":{other:`与备份相比，{count} 个块中有 {differing} 个不同：{blocks}`},"summary.matches":{other:`与备份一致（全部 {count} 个块）`},"summary.onlyInFull":`仅在全闪存读取中`,"summary.onlyInFullValue":{other:`{count} 个原厂读取无法访问的块：{blocks}`},"summary.rawDump":`全闪存读取（原样）`,"summary.rawDumpBadge":`内容相同，但补丁仍在其中`,"summary.image":`固件镜像（已解密，{bank}）`,"summary.verify":`验证`,"summary.toolbar":`压缩包操作`,"summary.download":`下载完整压缩包（运行文件）`,"runFile.eyebrow":`可选——用于以后继续运行`,"runFile.title":`运行文件`,"runFile.description":`本次运行的唯一记录。每个步骤之后（以及提前停止的步骤之后）都会自动下载；请保留最新的那个。要以后继续，或在出现问题后继续，请在这里加载它，本页会从中断的地方接着进行。`,"runFile.run":`运行`,"runFile.file":`文件`,"runFile.lastSaved":`上次保存`,"runFile.lastSavedValue":`在 {step} 之后——{at}（{bytes} B）`,"runFile.nextStep":`下一步`,"runFile.none":`没有正在进行的运行。步骤 02 会开始一次，你也可以在这里加载运行文件。`,"runFile.toolbar":`运行文件操作`,"runFile.load":`加载运行文件…`,"runFile.save":`再次保存运行文件`,"runFile.panel":`继续运行`,"status.noFile":`未选择运行文件。`,"status.notRun":`尚未运行。`,"status.running":`正在运行…`,"status.runningRestarts":`正在运行——相机会在此步骤中重启…`,"status.restarting":`相机正在重启——大约需要十秒…`,"status.waitConnect":`等待你的操作——请按“连接设备”并选择相机…`,"status.waitPlugBack":`等待你的操作——请重新插上相机，然后按“连接设备”…`,"status.waitReplug":`等待你的操作——请拔下相机再重新插上…`,"status.back":`相机已重新连接——正在继续…`,"status.swapped":`已停止——相机变了。请检查相机，然后重新运行该步骤。`,"status.noRun":`没有运行。`,"status.notCreated":`未创建——请查看上方的日志。`,"status.refused":`已拒绝——上方的步骤列表说明了缺少什么。`,"status.done":`{phase}——完成。你下载的运行文件是最新的。`,"status.doneReplug":`{phase}——完成，运行文件已保存。还原之前：请拔下相机，再重新插上，然后按“连接设备”。`,"status.backupRefused":`已拒绝——没有写入任何内容。请查看上方的日志。`,"status.failed":`失败——请查看上方的日志。`,"status.cancelled":`已取消——运行文件仍记录着运行停在何处。`,"status.readingFile":`正在读取运行文件…`,"status.doneEarlier":`之前已完成——从运行文件加载。`,"status.failedEarlier":`之前失败：{error}`,"status.resumed":`已从 {step} 继续。步骤列表会从那里接着进行。`,"status.notResumed":`未能继续——请查看上方的日志。`,"gate.needs":`需要{missing}`,"gate.noRun":`没有正在进行的运行——第一个步骤会创建运行`,"gate.runDone":`本次运行已完成——所有步骤都已完成`,"gate.alreadyDone":`已完成——继续运行将从 {step} 开始`,"gate.banksRead":`备份读取的槽位`,"gate.choice":`选择槽位——{why}`,"gate.bankRefused":`{bank} 无法写入：{reason}`,"gate.recoveryRoute":`恢复槽位路径（此版本只从{r} 运行，而不是{bank}）`,"gate.backupFirst":`闪存备份（在此步骤中最先运行）`,"gate.backup":`闪存备份`,"gate.patchStep":`补丁步骤`,"gate.patchOf":`{bank} 的补丁`,"gate.backupFile":`备份窗口文件`,"gate.capture":`{bank} 的采集数据`,"gate.derived":`{bank} 的推导镜像`,"gate.writeStep":`“写入”步骤（请先运行它，或从它继续）`,"gate.drainRefused":`全闪存读取在 {build} 上拒绝运行——{why}`,"gate.patchSummary":`{bank} 的补丁摘要（暂存长度）`,"gate.restoreRefused":`还原在 {build} 上拒绝运行——原始固件没有任何一种形式能存回为原始字节；本次运行将以完整镜像结束，补丁仍保留在相机中`,"gate.plaintext":`{bank} 的原厂明文（{file}，来自备份步骤）`,"gate.restoreFirst":`还原（在此步骤中最先运行）`,"gate.powerCycle":`断电重启的确认——请给相机断电重启（拔下再重新插上，或使用它的电源开关），然后使用重新运行的控件`,"error.cameraNotBack":`重试 {minutes} 分钟后相机仍未重新连接：{error}——如果 Chrome 没有弹出任何询问，请重新插拔相机并再次运行该步骤；如果日志提示重新连接，那么它等待的正是你点击“连接设备”`}};export{e as default};
